var e=JSON.parse(`{"big-toe":{"name":"Big Toe Pose","goodFor":"Hamstring stretch with active hand-to-foot connection.","instructions":"Stand with feet together. Fold forward and loop the big toes with the first two fingers of each hand (or hold a strap around the feet). Soften the knees so the spine can lengthen. On an inhale lift the chest halfway; on an exhale fold deeper. Keep the neck soft and weight slightly forward in the balls of the feet. To exit, release the toes, bend the knees, and roll or rise up."},"gorilla":{"name":"Gorilla Pose","goodFor":"Deep hamstring stretch and wrist extension.","instructions":"From a forward fold, slide the hands under the feet with palms facing up, toes against the wrists. Soften the knees; let the elbows bend. Lengthen the spine on the inhale and fold on the exhale. Jaw and neck relax. To exit, slide the hands out, bend the knees, and carefully rise."},"bird-of-paradise":{"name":"Bird of Paradise","goodFor":"Open-hip balance with a shoulder bind.","instructions":"From a bind in a forward fold or Extended Side Angle, carefully rise onto the standing leg and extend the bound leg out to the side. Standing knee soft; chest open. Gaze steady. Keep the breath smooth — back off if the shoulder or hamstring complains. To exit, re-bend the lifted knee and safely release the bind before standing tall."},"revolved-bird-of-paradise":{"name":"Revolved Bird of Paradise Pose","goodFor":"Builds mobility, strength, and awareness for Revolved Bird of Paradise Pose.","instructions":"From a revolved bind (often from a twisted lunge or fold), rise onto the standing foot and extend the bound leg while keeping the twist. Soften the standing knee. Lengthen the spine; gaze may follow the twist. To exit, bend the lifted knee, lower with control, and release the bind."},"upward-salute":{"name":"Upward Salute","goodFor":"Length through the side body; energizing start.","instructions":"From mountain, inhale and sweep both arms out and up beside the ears. Keep the ribs soft and the neck long; look slightly up only if comfortable. Ground through the feet as the fingertips reach. Shoulders stay away from the ears. Exhale to lower the arms or fold forward to leave the pose.","breathCue":"Inhale to reach up; keep shoulders soft.","modifications":["Hands to heart if shoulders are irritated"],"alignmentCues":["Biceps beside the ears","Tailbone heavy"]},"chair":{"name":"Chair Pose","goodFor":"Leg strength, ankle stability, and heat-building.","instructions":"Stand with feet together or hip-width. Bend the knees and sit the hips back as if into a chair, keeping weight in the heels. Reach arms up beside the ears or keep hands at the heart. Chest lifts; low back stays long. Knees track over the second and third toes. Breathe steadily. To exit, press into the feet and straighten the legs, or fold forward.","breathCue":"Steady breath in the belly and ribs.","modifications":["Shallower bend","Feet hip-width"],"deepen":["Sit lower only while knees track toes"],"commonMistakes":["Knees past toes unchecked","Chest collapsing"]},"high-lunge":{"name":"High Lunge","goodFor":"Leg strength, hip flexor stretch, and balance.","instructions":"Step one foot forward into a long stance; back heel lifts, back leg strong. Front knee bends over the ankle. Hips square forward; arms reach up or stay at the heart. Soften the shoulders. To exit, lower the hands and step the back foot forward, or fold over the front leg.","breathCue":"Inhale lift; exhale root through the feet.","modifications":["Shorten stance","Hands to heart"],"commonMistakes":["Front knee collapsing inward"]},"low-lunge":{"name":"Low Lunge","goodFor":"Deep hip-flexor opening and gentle backbend preparation.","instructions":"From Down Dog or standing, step one foot forward between the hands. Lower the back knee if comfortable; untuck the back toes. Front knee stacks over the ankle. Hands on the front thigh, blocks, or reach up. Square the hips forward gently. To exit, plant the hands and step back to Down Dog or fold.","breathCue":"Exhale to ease hips forward gently.","modifications":["Hands on front thigh"],"deepen":["Reach arms up when stable"],"avoidIf":["Knee cushioning needed — always pad"]},"eagle":{"name":"Eagle Pose","goodFor":"Balance, shoulder stretch, and outer-hip engagement.","instructions":"Bend both knees slightly. Wrap one thigh over the other and hook the foot behind the calf if available. Cross the arms opposite the legs: one elbow under the other, palms toward each other or touching. Sit the hips back; lift the elbows. Soft gaze. To exit, unwrap the limbs slowly and stand tall.","breathCue":"Steady breath through the nose.","modifications":["Cross once without wrapping","Sit on a chair"]},"standing-foot-behind-the-head":{"name":"Standing Foot Behind the Head Pose","goodFor":"Builds mobility, strength, and awareness for Standing Foot Behind the Head Pose.","instructions":"From standing, carefully bring one foot behind the head or high on the shoulders only if mobility allows — use a wall and never force the knee. Soften the standing leg. To exit, release the foot slowly with both hands supporting."},"standing-foot-to-head":{"name":"Standing Foot to Head Pose","goodFor":"Builds mobility, strength, and awareness for Standing Foot to Head Pose.","instructions":"Stand on one foot and draw the other foot toward the head with the hands or a strap. Soften the standing knee; pelvis steady. To exit, lower the foot with control."},"standing-foot-behind-the-head-forward-bend":{"name":"Standing Foot Behind the Head Forward Bend Pose","goodFor":"Builds mobility, strength, and awareness for Standing Foot Behind the Head Forward Bend Pose.","instructions":"From foot-behind-the-head standing prep, hinge forward carefully with support. Soften the standing knee. Keep the breath smooth. To exit, lift the torso and release the bound foot."},"half-standing-forward-bend":{"name":"Half Standing Forward Bend Pose","goodFor":"Builds mobility, strength, and awareness for Half Standing Forward Bend Pose.","instructions":"From a forward fold, place fingertips or hands on shins or blocks. Inhale and lift the chest halfway so the spine is long and roughly parallel to the floor. Gaze soft toward the floor; neck in line with the spine. Keep a soft bend in the knees if hamstrings are tight. Exhale to fold again or step back to leave.","breathCue":"Inhale to lift a long spine; gaze soft.","modifications":["Hands on thighs instead of shins"],"alignmentCues":["Fingertips under shoulders","Lengthen crown forward"]},"standing-forward-bend":{"name":"Standing Forward Bend Pose","goodFor":"Builds mobility, strength, and awareness for Standing Forward Bend Pose.","instructions":"From standing, hinge at the hips and fold the torso over the legs. Soften the knees as much as you need so the spine can lengthen. Let the head hang; hold elbows, shins, or the floor. Shift weight slightly into the balls of the feet. Breathe into the back body. To exit, bend the knees, engage the belly, and roll or rise with a long spine.","breathCue":"Exhale to fold; inhale to lengthen the spine slightly.","modifications":["Bend the knees generously","Hands to shins"],"deepen":["Straighten legs only if the spine stays long"],"avoidIf":["Acute low-back disc flare (keep knees bent)"],"commonMistakes":["Rounding hard from the low back","Locking knees"],"alignmentCues":["Hinge from the hips","Let the head hang heavy"]},"standing-half-bound-lotus-forward-bend":{"name":"Standing Half Bound Lotus Forward Bend Pose","goodFor":"Builds mobility, strength, and awareness for Standing Half Bound Lotus Forward Bend Pose.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Standing Half Bound Lotus Forward Bend Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"goddess":{"name":"Goddess Pose","goodFor":"Inner-thigh strength, hip opening, and heat.","instructions":"Take a wide stance with toes turned out roughly 45°. Bend the knees over the toes and sit the hips down. Arms may cactus at shoulder height or reach overhead. Keep the spine long; avoid tucking hard. Knees track in line with the toes. To exit, straighten the legs and turn the toes forward.","breathCue":"Inhale lift the heart; exhale bend the knees."},"half-moon":{"name":"Half Moon","goodFor":"Balance, hip strength, and lateral openness.","instructions":"From Triangle or a short stance, plant the front hand on a block or the floor ahead of the standing foot. Lift the back leg parallel to the floor and open the top hip and top arm skyward. Standing leg strong; soft knee. Gaze down, forward, or up. To exit, lower the lifted foot and return to Triangle or standing.","breathCue":"Inhale expand; exhale stabilize the standing leg.","modifications":["Keep lifted toes lower","Hand higher on block"]},"revolved-half-moon":{"name":"Revolved Half Moon","goodFor":"Balance with a detoxifying twist.","instructions":"From a short fold or Revolved Triangle, plant the opposite hand and lift the back leg. Twist the chest open toward the standing-leg side; top arm reaches up. Hips stack as much as balance allows. Soft gaze. To exit, lower the lifted foot and untwist carefully."},"extended-standing-hand-to-big-toe":{"name":"Extended Standing Hand to Big Toe Pose","goodFor":"Builds mobility, strength, and awareness for Extended Standing Hand to Big Toe Pose.","instructions":"Stand tall. Hold one big toe or a strap and extend that leg forward, then open it to the side as mobility allows. Soften the standing knee; pelvis level. To exit, return the leg to center and release."},"revolved-standing-hand-to-big-toe":{"name":"Revolved Standing Hand to Big Toe Pose","goodFor":"Builds mobility, strength, and awareness for Revolved Standing Hand to Big Toe Pose.","instructions":"Hold one foot with the opposite hand or a strap and gently twist while the leg extends. Soften the standing knee. Lengthen the spine before deepening. To exit, untwist, bend the knee, and release."},"standing-hand-to-big-toe":{"name":"Standing Hand to Big Toe Pose","goodFor":"Builds mobility, strength, and awareness for Standing Hand to Big Toe Pose.","instructions":"Begin standing with steady feet and a soft gaze. Arrange the body into Standing Hand to Big Toe Pose: place the feet first, then the hands or arms, then lengthen the spine. Soften any joint that feels compressed; keep the breath easy. Hold at a depth you can sustain without gripping the jaw. To exit, reverse the entry with control and return to mountain or a forward fold before continuing."},"mountain":{"name":"Mountain Pose","goodFor":"Posture, grounding, and body awareness.","instructions":"Stand with feet parallel, hip-width or together, weight even on both feet. Soften the knees slightly and lengthen the spine as if a string lifts the crown. Roll the shoulders back and down; arms rest by the sides with palms open. Gaze soft and forward. Breathe steadily through the nose. To exit, simply step into your next shape or bend the knees and fold.","breathCue":"Breathe steadily; lengthen on the inhale.","modifications":["Feet hip-width if balance feels unsteady"],"deepen":["Close the eyes for 3 breaths"],"commonMistakes":["Locking the knees","Ribs thrusting forward"],"alignmentCues":["Root through all four corners of the feet","Soften knees and lift the crown"]},"pyramid":{"name":"Pyramid Pose","goodFor":"Intense hamstring stretch with hip squaring.","instructions":"From a short lunge stance, both feet face forward and the legs straighten (soft knees ok). Hinge at the hips and fold over the front leg. Hands frame the front foot or rest on blocks. Square the hips toward the front. Lengthen the spine on the inhale; deepen the fold on the exhale. To exit, lift the chest halfway and step the feet together."},"extended-side-angle":{"name":"Extended Side Angle","goodFor":"Deep hip and side-body opening with leg strength.","instructions":"From Warrior II, tip the torso over the bent front leg. Rest the front forearm on the thigh or the hand on a block or the floor inside the front foot. Top arm reaches over the ear or straight up. Lengthen both sides of the waist. Gaze up, forward, or down. To exit, press into the feet and rise back to Warrior II.","breathCue":"Inhale open the top ribs; exhale ground the feet.","modifications":["Forearm on front thigh"]},"standing-splits":{"name":"Standing Splits Pose","goodFor":"Builds mobility, strength, and awareness for Standing Splits Pose.","instructions":"From a forward fold on one leg, shift weight into the standing foot and lift the other leg high behind you. Hands frame the standing foot or hold the ankle. Soften the standing knee; hips stay relatively square. To exit, lower the lifted leg and return to a fold or stand."},"dancer":{"name":"Dancer Pose","goodFor":"Balance, front-body stretch, and focus.","instructions":"Stand on one foot, hold the opposite foot behind you, and tip forward as you kick the foot up and back. Reach the free arm forward. Soften the standing knee. To exit, return upright and release the foot."},"tree":{"name":"Tree Pose","goodFor":"Balance, focus, and hip opening on the lifted leg.","instructions":"Stand on one foot. Place the sole of the other foot on the inner calf or thigh — never on the knee. Hip of the bent leg opens gently. Hands at the heart or reach overhead. Gaze soft on a fixed point. Lengthen the spine. To exit, lower the foot with control and switch when ready.","breathCue":"Soft steady breath; soften the jaw.","modifications":["Toes on the floor","Foot to ankle (not knee)"],"deepen":["Gaze up when steady"],"commonMistakes":["Foot pressing into the knee joint"]},"triangle":{"name":"Triangle Pose","goodFor":"Side-body length, hamstring stretch, and spinal mobility.","instructions":"From a wide stance, straighten the front leg and tip the torso over it. Front hand rests on shin, ankle, block, or floor; top arm reaches skyward. Keep both sides of the waist long; avoid collapsing into the front hip. Soften the knees slightly if needed. Gaze up, forward, or down. To exit, engage the core and rise with a long spine.","breathCue":"Inhale lengthen; exhale hinge without collapsing.","modifications":["Hand higher on shin","Shorter stance"],"deepen":["Top arm stacks only when chest is open"],"commonMistakes":["Rounding forward","Hyperextending front knee"]},"revolved-triangle":{"name":"Revolved Triangle","goodFor":"Twisting digestion support with hamstring stretch.","instructions":"From Pyramid stance, place one hand outside or inside the front foot (use a block). Inhale to lengthen; exhale to twist the torso toward the front leg, top arm reaching up. Keep hips relatively level. Soft knees. Gaze up or down. To exit, untwist and lift the torso, then step the feet together.","breathCue":"Exhale to twist; never hold the breath.","modifications":["Hand to shin","Bent front knee"],"avoidIf":["Late pregnancy","Acute disc issues — keep twists mild"],"commonMistakes":["Forcing the twist from the neck"]},"warrior-i":{"name":"Warrior I Pose","goodFor":"Builds mobility, strength, and awareness for Warrior I Pose.","instructions":"From a lunge or Down Dog, step one foot forward between the hands and rise. Front knee bends over the ankle; back leg straight with the heel angled in. Square the hips forward as much as comfortable. Reach arms up; shoulders soft. Gaze forward. Breathe steadily. To exit, lower the hands and step back, or straighten the front leg.","breathCue":"Inhale lift the chest; exhale root the back heel.","modifications":["Hands to hips","Shorten stance"],"commonMistakes":["Front knee collapsing","Overarching lumbar"],"alignmentCues":["Front knee over ankle","Back foot angled ~45°"]},"warrior-ii":{"name":"Warrior II Pose","goodFor":"Builds mobility, strength, and awareness for Warrior II Pose.","instructions":"Take a wide stance with feet roughly one leg-length apart. Turn the front toes out 90° and the back foot in slightly. Bend the front knee over the ankle; arms reach to the sides at shoulder height. Gaze over the front hand. Hips open to the side wall. Soften the shoulders. To exit, straighten the front leg and lower the arms, or cartwheel the hands down.","breathCue":"Breathe into the side body; gaze soft over front fingers.","modifications":["Hands on hips","Shorten stance"],"deepen":["Bend front knee deeper when thigh is stable"],"alignmentCues":["Shoulders over hips","Front knee tracks second toe"]},"warrior-iii":{"name":"Warrior III Pose","goodFor":"Builds mobility, strength, and awareness for Warrior III Pose.","instructions":"From standing or Warrior I, shift weight into one foot and tip the torso forward as the other leg lifts behind you. Aim for a T shape: torso and lifted leg roughly parallel to the floor. Arms reach forward, back, or to the heart. Square the hips toward the floor. Soft gaze. To exit, step the lifted foot down with control.","breathCue":"Steady breath; do not hold it for balance.","modifications":["Hands to blocks","Keep lifted toes on floor"],"avoidIf":["Acute ankle sprain on standing leg"],"commonMistakes":["Hips stacking open","Locking standing knee"]},"wide-legged-forward-bend-i":{"name":"Wide Legged Forward Bend I Pose","goodFor":"Builds mobility, strength, and awareness for Wide Legged Forward Bend I Pose.","instructions":"Stand with a wide stance, toes slightly in. Hinge at the hips and fold forward; hands to the floor, blocks, or a bind. Keep weight even in both feet. Soften the knees if hamstrings are tight. To exit, engage the belly and rise with a long spine, then step the feet in."},"wide-legged-forward-bend-ii":{"name":"Wide Legged Forward Bend II Pose","goodFor":"Builds mobility, strength, and awareness for Wide Legged Forward Bend II Pose.","instructions":"Begin standing with steady feet and a soft gaze. Arrange the body into Wide Legged Forward Bend II Pose: place the feet first, then the hands or arms, then lengthen the spine. Soften any joint that feels compressed; keep the breath easy. Hold at a depth you can sustain without gripping the jaw. To exit, reverse the entry with control and return to mountain or a forward fold before continuing."},"wide-legged-forward-bend-iii":{"name":"Wide Legged Forward Bend III Pose","goodFor":"Builds mobility, strength, and awareness for Wide Legged Forward Bend III Pose.","instructions":"Begin standing with steady feet and a soft gaze. Arrange the body into Wide Legged Forward Bend III Pose: place the feet first, then the hands or arms, then lengthen the spine. Soften any joint that feels compressed; keep the breath easy. Hold at a depth you can sustain without gripping the jaw. To exit, reverse the entry with control and return to mountain or a forward fold before continuing."},"wide-legged-forward-bend-iv":{"name":"Wide Legged Forward Bend IV Pose","goodFor":"Builds mobility, strength, and awareness for Wide Legged Forward Bend IV Pose.","instructions":"Take a wide stance and fold; clasp the hands behind the back and fold deeper, or use the traditional bind for this variation. Soften the knees. Keep weight even in both feet. To exit, release the hands, lift the chest, and step the feet in."},"revolved-wide-legged-forward-bend":{"name":"Revolved Wide Legged Forward Bend","goodFor":"Builds mobility, strength, and awareness for Revolved Wide Legged Forward Bend.","instructions":"From a wide-legged standing fold, reach one hand to the opposite foot and open the other arm skyward, twisting the torso. Soften the knees. Gaze up or down. To exit, release to a neutral fold, then rise."},"side-wide-legged-forward-bend":{"name":"Side Wide Legged Forward Bend","goodFor":"Builds mobility, strength, and awareness for Side Wide Legged Forward Bend.","instructions":"Begin standing with steady feet and a soft gaze. Arrange the body into Side Wide Legged Forward Bend: place the feet first, then the hands or arms, then lengthen the spine. Soften any joint that feels compressed; keep the breath easy. Hold at a depth you can sustain without gripping the jaw. To exit, reverse the entry with control and return to mountain or a forward fold before continuing."},"archers":{"name":"Archer\\\\","goodFor":"Builds mobility, strength, and awareness for Archer\\\\","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Archer\\\\, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"boat":{"name":"Boat Pose","goodFor":"Deep core strength and balance.","instructions":"Sit with knees bent, feet on the floor. Lean back slightly, lift the feet, and balance on the sit bones. Shins parallel to the floor (or legs straight). Arms reach forward beside the knees. Spine long; chest open. Soften the neck. To exit, lower the feet and sit upright.","breathCue":"Steady breath; do not brace by holding breath.","modifications":["Hold the thighs","Feet down"]},"bound-angle":{"name":"Bound Angle","goodFor":"Hip and groin flexibility.","instructions":"Sit tall, bring the soles of the feet together, and let the knees fall open. Hold the feet or ankles. Sit on a blanket if the low back rounds. Fold forward only if the spine stays long. Soften the inner thighs. To exit, use the hands to close the knees and extend the legs.","breathCue":"Soft belly breath; no forcing the knees.","modifications":["Sit higher","Feet farther from pelvis"]},"both-feet-behind-the-head-i":{"name":"Both Feet Behind the Head I Pose","goodFor":"Builds mobility, strength, and awareness for Both Feet Behind the Head I Pose.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Both Feet Behind the Head I Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"cow-face":{"name":"Cow Face Pose","goodFor":"Hip and shoulder opening together.","instructions":"Sit with knees stacked (one on top of the other) or simply cross-legged if hips are tight. Reach one arm up and bend the elbow; the other arm reaches behind the back — clasp or hold a strap. Sit tall. Soften the jaw. To exit, release the arms and switch the leg and arm positions."},"easy":{"name":"Easy Pose","goodFor":"Builds mobility, strength, and awareness for Easy Pose.","instructions":"Sit cross-legged with a tall spine. If the knees are high, sit on a folded blanket. Hands rest on the thighs or in the lap. Soften the shoulders and jaw. Breathe steadily through the nose. To exit, uncross the legs slowly and stretch them forward."},"fire-log":{"name":"Fire Log Pose","goodFor":"Deep outer-hip stretch; IT-band region relief.","instructions":"Sit with one shin parallel to the front of the mat and stack the other shin on top (ankle over knee as available). Sit on a blanket if needed. Fold forward only with a long spine. Soften the hips. To exit, carefully unstack the legs and shake them out."},"embryo-in-womb":{"name":"Embryo in Womb Pose","goodFor":"Builds mobility, strength, and awareness for Embryo in Womb Pose.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Embryo in Womb Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"foot-behind-the-head-i":{"name":"Foot Behind the Head I Pose","goodFor":"Builds mobility, strength, and awareness for Foot Behind the Head I Pose.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Foot Behind the Head I Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"foot-behind-the-head-ii":{"name":"Foot Behind the Head II Pose","goodFor":"Builds mobility, strength, and awareness for Foot Behind the Head II Pose.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Foot Behind the Head II Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"seated-forward-bend-i":{"name":"Seated Forward Bend I Pose","goodFor":"Builds mobility, strength, and awareness for Seated Forward Bend I Pose.","instructions":"From Staff, inhale to lengthen the spine, exhale hinge at the hips and fold over the legs. Hold the feet, shins, or a strap. Soften the knees if the low back rounds. Keep the neck long. To exit, inhale to lift the torso with a long spine.","breathCue":"Inhale lengthen; exhale fold from the hips.","modifications":["Bent knees","Sit on a folded blanket"],"avoidIf":["Acute hamstring tear"]},"seated-forward-bend-ii":{"name":"Seated Forward Bend II Pose","goodFor":"Builds mobility, strength, and awareness for Seated Forward Bend II Pose.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Seated Forward Bend II Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"seated-forward-bend-iii":{"name":"Seated Forward Bend III Pose","goodFor":"Builds mobility, strength, and awareness for Seated Forward Bend III Pose.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Seated Forward Bend III Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"seated-forward-bend-iv":{"name":"Seated Forward Bend IV Pose","goodFor":"Builds mobility, strength, and awareness for Seated Forward Bend IV Pose.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Seated Forward Bend IV Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"seated-half-bound-lotus-forward-bend":{"name":"Seated Half Bound Lotus Forward Bend Pose","goodFor":"Builds mobility, strength, and awareness for Seated Half Bound Lotus Forward Bend Pose.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Seated Half Bound Lotus Forward Bend Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"seated-three-limbed-forward-bend":{"name":"Seated Three Limbed Forward Bend Pose","goodFor":"Builds mobility, strength, and awareness for Seated Three Limbed Forward Bend Pose.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Seated Three Limbed Forward Bend Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"garland":{"name":"Garland Pose","goodFor":"Hip opening, ankle mobility, and pelvic floor awareness.","instructions":"From standing, feet hip-width or wider, toes slightly out. Bend the knees deeply into a squat, heels down if possible (elevate heels on a roll if not). Elbows press inner knees; hands at the heart. Spine long; chest lifted. To exit, plant the hands and straighten the legs, or sit back onto the floor.","breathCue":"Steady breath in a low squat.","modifications":["Sit on a block"]},"seated-gate":{"name":"Seated Gate Pose","goodFor":"Builds mobility, strength, and awareness for Seated Gate Pose.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Seated Gate Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"head-to-knee-i":{"name":"Head to Knee I Pose","goodFor":"Builds mobility, strength, and awareness for Head to Knee I Pose.","instructions":"Sit with one leg extended and the other foot to the inner thigh. Square the torso over the extended leg and fold. Hold the foot or a strap. Soften the extended knee if needed. Keep both sit bones grounded. To exit, lift the torso and switch legs when ready."},"head-to-knee-ii":{"name":"Head to Knee II Pose","goodFor":"Builds mobility, strength, and awareness for Head to Knee II Pose.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Head to Knee II Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"head-to-knee-iii":{"name":"Head to Knee III Pose","goodFor":"Builds mobility, strength, and awareness for Head to Knee III Pose.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Head to Knee III Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"hero":{"name":"Hero Pose","goodFor":"Quad stretch and meditation seat.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Hero Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"heron":{"name":"Heron Pose","goodFor":"Intense hamstring stretch with core engagement.","instructions":"Sit tall. Hold one foot with both hands and extend that leg up as straight as comfortable; the other leg stays bent or extended on the floor. Spine long; shoulders soft. To exit, bend the raised knee and release the foot."},"noose":{"name":"Noose Pose","goodFor":"Deep twist with ankle and shoulder mobility.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Noose Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"half-pigeon":{"name":"Half Pigeon","goodFor":"Accessible pigeon variation for hip opening.","instructions":"From Down Dog or a lunge, bring one shin forward across the mat (ankle near the opposite wrist as comfortable). Extend the back leg straight behind. Square the hips; use a blanket under the front hip if needed. Fold forward over the front leg or stay upright. To exit, tuck the back toes, lift, and step back.","breathCue":"Long soft exhales into the outer hip.","modifications":["Figure-four on the back","Keep torso upright"],"avoidIf":["Sharp knee pain — switch to figure-four"],"commonMistakes":["Forcing the front shin parallel"]},"lotus":{"name":"Lotus Pose","goodFor":"Classic meditation seat; deep hip opening.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Lotus Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"sage-marichis-i":{"name":"Sage Marichi\\\\","goodFor":"Builds mobility, strength, and awareness for Sage Marichi\\\\","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Sage Marichi\\\\, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"side-lunge":{"name":"Side Lunge","goodFor":"Inner-thigh strength and lateral hip mobility.","instructions":"From a wide stance, bend one knee and shift the hips toward that heel while the other leg stays long. Hands on the floor, blocks, or thigh. Both feet grounded; toes of the bent leg point roughly the same way as the knee. Spine long. To exit, press into the bent leg and return to center, then switch."},"front-splits":{"name":"Front Splits","goodFor":"Full front-leg splits flexibility.","instructions":"Come to the floor and set up Front Splits with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"half-splits":{"name":"Half Splits Pose","goodFor":"Builds mobility, strength, and awareness for Half Splits Pose.","instructions":"From a low lunge, shift the hips back over the back knee and straighten the front leg as much as comfortable. Flex the front toes toward the ceiling. Hinge and fold over the front leg; hands frame the leg or rest on blocks. Keep the hips square. To exit, bend the front knee and shift forward into lunge."},"wide-splits":{"name":"Wide Splits","goodFor":"Wide-leg flexibility and groin opening.","instructions":"Sit with the legs open wide. Hinge at the hips and walk the hands forward, keeping the spine long. Flex the feet. Soften the knees slightly if the hamstrings protest. To exit, walk the hands in and bring the legs together."},"staff":{"name":"Staff Pose","goodFor":"Seated posture foundation and leg engagement.","instructions":"Sit with both legs extended straight, feet flexed. Sit tall on the sit bones; lengthen the spine. Hands beside the hips press lightly down. Soften the front ribs. To exit, bend the knees or fold forward into the next shape."},"thunderbolt":{"name":"Thunderbolt Pose","goodFor":"Digestion-friendly seat and ankle mobility.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Thunderbolt Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"toe-stand":{"name":"Toe Stand","goodFor":"Ankle strength and intense balance.","instructions":"From a squat or Half Lotus prep, carefully rise onto the ball of the standing foot with the other foot bound, using hands on the floor for balance as needed. Soften the standing ankle. Spine long. To exit, lower the hands and hips with control."},"banana":{"name":"Banana Pose","goodFor":"Side-body stretch and restorative lateral release.","instructions":"Lie on your back. Walk both feet and both arms toward one side so the body makes a gentle banana curve. Soften the opposite side body. Rest the head comfortably. To exit, return to center and switch the curve."},"bridge":{"name":"Bridge Pose","goodFor":"Glute strength, chest opening, and gentle inversion.","instructions":"Lie on your back, knees bent, feet hip-width under the knees. Press into the feet and lift the hips. Interlace hands under the back or keep arms by the sides. Soften the neck; gaze up. Knees track over the ankles. To exit, release the hands and lower the spine vertebra by vertebra.","breathCue":"Inhale lift; exhale keep knees tracking.","modifications":["Hold a lower height"],"avoidIf":["Acute neck issues — keep gaze neutral, no turning head"]},"corpse":{"name":"Corpse Pose","goodFor":"Integration, rest, and nervous-system reset.","instructions":"Lie on your back with legs extended and arms a little away from the body, palms up. Soften the feet and let them fall open. Close the eyes if comfortable. Release the jaw, shoulders, and belly. Breathe naturally without effort. Stay until you are ready to roll to one side and slowly sit up.","breathCue":"Natural breath; no control needed.","modifications":["Support the head","Side-lying if needed"],"alignmentCues":["Palms soft","Feet fall open"]},"fish":{"name":"Fish Pose","goodFor":"Chest and throat opening; counterpose to forward folds.","instructions":"Lie on your back. Slide hands under the hips, palms down. Press into the elbows and lift the chest; crown of the head may rest lightly on the mat. Legs extended or knees bent. Soften the throat. To exit, lift the head first, then lower the spine.","breathCue":"Inhale open the throat; keep jaw soft.","modifications":["Supported fish on a bolster"]},"supine-foot-to-head":{"name":"Supine Foot to Head Pose","goodFor":"Builds mobility, strength, and awareness for Supine Foot to Head Pose.","instructions":"Come to the floor and set up Supine Foot to Head Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"extended-supine-hand-to-big-toe":{"name":"Extended Supine Hand to Big Toe Pose","goodFor":"Builds mobility, strength, and awareness for Extended Supine Hand to Big Toe Pose.","instructions":"Come to the floor and set up Extended Supine Hand to Big Toe Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"supine-hand-to-big-toe":{"name":"Supine Hand to Big Toe Pose","goodFor":"Builds mobility, strength, and awareness for Supine Hand to Big Toe Pose.","instructions":"Lie on your back. Loop a strap around one foot or hold the big toe; extend that leg toward the ceiling (or as high as comfortable). Other leg stays long on the floor or bent. Soften the shoulders. Keep the pelvis level. To exit, bend the raised knee and release the strap or toe."},"happy-baby":{"name":"Happy Baby","goodFor":"Hip opening and playful hamstring stretch.","instructions":"Lie on your back. Bend the knees toward the chest and hold the outer feet or big toes. Open the knees wider than the torso; soles face up. Gently rock or stay still. Soften the low back into the mat. To exit, release the feet and extend the legs.","breathCue":"Playful free breath.","modifications":["Hold the backs of the thighs"]},"sleeping-yogi":{"name":"Sleeping Yogi Pose","goodFor":"Builds mobility, strength, and awareness for Sleeping Yogi Pose.","instructions":"Come to the floor and set up Sleeping Yogi Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"supine-spinal-twist":{"name":"Supine Spinal Twist Pose","goodFor":"Builds mobility, strength, and awareness for Supine Spinal Twist Pose.","instructions":"Lie on your back with knees bent. Drop both knees (or one) to one side; extend arms to a T or cactus. Soften the opposite shoulder toward the floor without forcing. Gaze may follow the opposite way. Breathe into the ribs. To exit, return the knees to center and switch sides.","breathCue":"Exhale knees across; keep both shoulders heavy.","modifications":["Stack a pillow under the knees"]},"supine-straddle":{"name":"Supine Straddle","goodFor":"Gravity-assisted wide-leg stretch.","instructions":"Come to the floor and set up Supine Straddle with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"waterfall":{"name":"Waterfall Pose","goodFor":"Gentle inversion and leg drainage without a wall.","instructions":"Lie on your back near a wall (or lift the legs without a wall). Extend the legs up so the heels are above the hips. Arms rest by the sides, palms up. Soften the face and belly. Breathe quietly. To exit, bend the knees and roll to one side before sitting up.","breathCue":"Long soft breaths; eyes soft.","avoidIf":["Glaucoma / unmanaged high ICP — keep legs lower"]},"wind-removing":{"name":"Knees to Chest","goodFor":"Low-back relief and digestion support.","instructions":"Lie on your back. Hug one or both knees into the chest. Soften the shoulders and jaw. Rock gently if it feels good. Breathe into the low back. To exit, release the feet to the floor.","breathCue":"Exhale hug; inhale release slightly."},"bow":{"name":"Bow Pose","goodFor":"Deep front-body stretch with back strength.","instructions":"Lie face-down. Bend the knees and reach back to hold the outer ankles or feet. Kick the feet into the hands to lift the chest and thighs. Soften the neck. Breathe into the belly. To exit, release the feet and lower slowly.","breathCue":"Inhale kick into the hands; breathe into the belly.","modifications":["Half bow one side at a time"]},"half-bow":{"name":"Half Bow","goodFor":"Asymmetric backbend and quad stretch.","instructions":"Come to the floor and set up Half Bow with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"childs":{"name":"Child’s Pose","goodFor":"Rest, back release, and nervous-system downshift.","instructions":"Kneel with big toes together and knees hip-width or wider. Sit the hips toward the heels and fold the torso forward, forehead toward the mat. Arms reach forward or rest by the sides. Soften the belly and jaw. Breathe into the back ribs. To exit, walk the hands in and rise slowly to kneeling.","breathCue":"Exhale soften the belly toward the thighs.","modifications":["Knees wide","Arms alongside body"]},"cobra":{"name":"Cobra Pose","goodFor":"Back strength and chest opening.","instructions":"Lie face-down, tops of feet on the mat, hands under the shoulders. Press lightly into the hands to lift the chest; elbows stay soft and close to the body. Pubic bone stays down. Shoulders away from the ears. To exit, lower the chest with control.","breathCue":"Inhale lift; keep pelvis heavy.","modifications":["Keep elbows bent","Hands farther forward"]},"reverse-corpse":{"name":"Reverse Corpse","goodFor":"Prone resting pose; alternative Savasana.","instructions":"Set up Reverse Corpse with props nearby so you can fully rest. Support the body so muscles do not grip; add blankets under knees, spine, or arms as needed. Close the eyes if comfortable and let the breath become quiet and natural. Stay soft in the face and belly. To exit, move slowly — roll to one side and pause before sitting up."},"puppy":{"name":"Puppy Pose","goodFor":"Shoulder and upper-back opening without a full child’s pose.","instructions":"From table, walk the hands forward and keep the hips stacked over the knees. Lower the chest and forehead (or chin) toward the mat. Arms active; shoulders melt down. Soften the belly. To exit, walk the hands back under the shoulders.","breathCue":"Exhale melt the chest; hips stay high."},"frog":{"name":"Frog Pose","goodFor":"Deep quad stretch and front-body opening.","instructions":"From all fours or belly, open the knees wide and bring the feet in line with the knees, ankles flexed. Lower to the forearms if comfortable. Soften the hips — use padding under the knees. To exit, bring the knees in and sit back toward Child."},"locust-i":{"name":"Locust I Pose","goodFor":"Builds mobility, strength, and awareness for Locust I Pose.","instructions":"Come to the floor and set up Locust I Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing.","breathCue":"Inhale lift; exhale lengthen."},"locust-ii":{"name":"Locust II Pose","goodFor":"Builds mobility, strength, and awareness for Locust II Pose.","instructions":"Come to the floor and set up Locust II Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"locust-iii":{"name":"Locust III Pose","goodFor":"Builds mobility, strength, and awareness for Locust III Pose.","instructions":"Come to the floor and set up Locust III Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"sage-gherandas":{"name":"Sage Gheranda\\\\","goodFor":"Builds mobility, strength, and awareness for Sage Gheranda\\\\","instructions":"Sit tall and arrange the legs and twist or fold as taught for this sage variation. Lengthen the spine on the inhale before deepening. Soften the shoulders. To exit, release the twist or fold and straighten the legs."},"snake":{"name":"Snake Pose","goodFor":"Chest opening with upper-back strength.","instructions":"Come to the floor and set up Snake Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"sphinx":{"name":"Sphinx Pose","goodFor":"Gentle backbend; builds low-back awareness.","instructions":"Lie face-down. Prop on the forearms with elbows under the shoulders. Press the forearms down to lift the chest gently. Legs long and active. Soften the shoulders. To exit, lower the chest and rest a cheek on the mat.","breathCue":"Easy inhale into the low belly and chest."},"tortoise":{"name":"Tortoise Pose","goodFor":"Deep forward fold and shoulder release.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Tortoise Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"table":{"name":"Table Pose","goodFor":"Builds mobility, strength, and awareness for Table Pose.","instructions":"Come to hands and knees. Stack shoulders over wrists and hips over knees. Spread the fingers; press the floor away. Keep the spine long and the neck neutral. Soften the elbows. To exit, sit back to Child or step into your next pose.","breathCue":"Neutral steady breath.","modifications":["Pad the knees"]},"camel":{"name":"Camel Pose","goodFor":"Deep front-body stretch and heart opening.","instructions":"Kneel with knees hip-width. Hands on the low back or reach for the heels. Lift the chest and gently arch back; keep the hips over the knees. Soften the throat; gaze up only if the neck is happy. To exit, bring the hands to the low back and lift the chest to return upright.","breathCue":"Inhale lift the chest; exhale hands toward heels only if safe.","modifications":["Hands on sacrum","Toes tucked"],"avoidIf":["Neck injury — keep chin slightly tucked, no dropping head"]},"cat":{"name":"Cat Pose","goodFor":"Spinal mobility and breath-linked movement.","instructions":"Come to the floor and set up Cat Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing.","breathCue":"Exhale round; inhale prepare for cow."},"cow":{"name":"Cow Pose","goodFor":"Spinal extension and chest opening paired with Cat.","instructions":"Come to the floor and set up Cow Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing.","breathCue":"Inhale lift the heart; gaze soft."},"cat-cow":{"name":"Cat-Cow","goodFor":"Warm the spine and link breath to movement.","description":"Alternate cat and cow with the breath — round on the exhale, arch on the inhale. Usually several rounds, not two static holds.","instructions":"Start on hands and knees, shoulders over wrists, hips over knees. Inhale to drop the belly and lift the chest and gaze (cow). Exhale to round the spine, tuck the tail, and look toward the navel (cat). Flow with the breath. To exit, return to a neutral tabletop spine.","breathCue":"Inhale to cow (belly soft, heart forward); exhale to cat (round the spine). Keep alternating for several rounds.","modifications":["Pad the knees","Fewer rounds if wrists are sensitive"],"alignmentCues":["Wrists under shoulders, knees under hips","Move with the breath — one shape per inhale or exhale"]},"dolphin":{"name":"Dolphin Pose","goodFor":"Shoulder strength and Downdog variation on forearms.","instructions":"From forearms and knees, tuck the toes and lift the hips into an inverted V on the forearms. Elbows shoulder-width; clasp hands or keep forearms parallel. Soften the knees so the spine lengthens. Heels reach down. To exit, lower the knees to the mat.","breathCue":"Long exhales; neck soft.","modifications":["Knees down","Wider elbows"]},"downward-facing-dog":{"name":"Downward-Facing Dog Pose","goodFor":"Builds mobility, strength, and awareness for Downward-Facing Dog Pose.","instructions":"From hands and knees, tuck the toes, lift the hips, and straighten the legs into an inverted V. Hands shoulder-width, feet hip-width. Press evenly into the palms; lengthen the spine toward the hips. Soften the knees if needed so the back stays long. Heels reach toward the floor without forcing. Long soft breaths. To exit, drop the knees or step/jump forward.","breathCue":"Long soft breaths; jaw relaxed.","modifications":["Bend knees","Widen stance"],"deepen":["Press thighs back; heels toward floor without forcing"],"avoidIf":["Uncontrolled high blood pressure — keep head higher"],"commonMistakes":["Rounded upper back","Dumping into shoulders"],"alignmentCues":["Hands shoulder-width","Hips reach up and back"]},"eight-point":{"name":"Eight-Point Pose","goodFor":"Classic Ashtanga transition strength.","instructions":"From hands and knees or a modified plank, lower the chest and chin to the mat while the hips stay lifted (knees, chest, and chin touch). Elbows hug in. To exit, slide forward to Cobra or push back to Child."},"humble-flamingo":{"name":"Humble Flamingo Pose","goodFor":"Builds mobility, strength, and awareness for Humble Flamingo Pose.","instructions":"From a standing flamingo or dancer prep, fold forward while holding the lifted foot, bringing the torso toward the standing leg. Soften the standing knee. To exit, rise and release the foot."},"gate":{"name":"Gate Pose","goodFor":"Side-body length and breathing space.","instructions":"Kneel, then extend one leg out to the side with the foot grounded. Reach the same-side arm down the extended leg; top arm arcs overhead. Keep the hips square-ish to the front. Soften the side waist. To exit, bring the torso upright and draw the extended knee back in."},"horse":{"name":"Horse Pose","goodFor":"Hip opening with unusual balance challenge.","instructions":"Take a wide stance with toes turned out. Bend the knees deeply over the toes and sit the hips low, similar to Goddess. Hands at the heart or on the thighs. Spine tall. To exit, straighten the legs and bring the feet together."},"lizard":{"name":"Lizard Pose","goodFor":"Intense hip and groin opening.","instructions":"From a low lunge, walk both hands inside the front foot and lower onto the forearms if available (or keep hands on blocks). Front toes may turn out slightly. Soften the back knee or keep it lifted. Breathe into the inner hip. To exit, plant the hands, step back, and switch sides later.","breathCue":"Exhale ease hips forward within comfort."},"lunge":{"name":"Classic Lunge","goodFor":"Transitional lunge used in sun salutations.","instructions":"Step one foot forward between the hands with the back leg long and strong (heel up). Stack the front knee over the ankle. Hands frame the front foot or lift. Keep the hips level and the spine long. Breathe steadily. To exit, step the front foot back or rise to standing.","breathCue":"Inhale length; exhale settle the hips.","modifications":["Back knee down","Hands on blocks"],"alignmentCues":["Front knee tracks over ankle","Back heel stacked under toes"]},"crooked-monkey":{"name":"Crooked Monkey Pose","goodFor":"Builds mobility, strength, and awareness for Crooked Monkey Pose.","instructions":"From a lunge or arm-balance prep, arrange the legs in the crooked-monkey bind and lean onto the hands to lift if available. Soften the elbows. To exit, lower and release the bind carefully."},"pigeon":{"name":"Pigeon Pose","goodFor":"Deep hip opening; prep for seated poses.","instructions":"Come to the floor and set up Pigeon Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"one-legged-king-pigeon":{"name":"One Legged King Pigeon Pose","goodFor":"Builds mobility, strength, and awareness for One Legged King Pigeon Pose.","instructions":"From Half Pigeon, bend the back knee and reach for the foot with one or both hands (use a strap). Gently kick into the hand to open the chest. Keep the front hip supported. To exit, release the back foot first, then step back to Down Dog."},"plank":{"name":"Plank Pose","goodFor":"Core endurance and shoulder stability.","instructions":"From hands and knees or a push-up position, stack shoulders over wrists and step the feet back. Form one long line from heels to crown. Press the floor away; draw the navel gently in. Legs strong; heels reaching back. Soften the jaw and breathe steadily. To exit, lower the knees or move into Chaturanga or Down Dog.","breathCue":"Steady breath; do not hold the breath.","modifications":["Knees down","Hands on blocks"],"deepen":["Push the floor away; one long line"],"avoidIf":["Acute wrist pain — use fists or forearms"],"commonMistakes":["Hips sagging","Shoulders dumping toward ears"],"alignmentCues":["Press mounds of the index fingers","Draw navel gently in"]},"upward-plank":{"name":"Upward Plank","goodFor":"Posterior-chain strength and front-body stretch.","instructions":"Sit with legs extended, hands behind the hips with fingers forward or out. Press into the hands and feet to lift the hips; toes may point down. Soften the neck or look forward. To exit, lower the hips and sit."},"four-limbed-staff":{"name":"Four Limbed Staff Pose","goodFor":"Builds mobility, strength, and awareness for Four Limbed Staff Pose.","instructions":"From plank, bend the elbows straight back along the ribs and lower the body halfway, hovering parallel to the floor. Keep the chest broad and the shoulders at elbow height. Engage the core and legs. Gaze slightly forward. Exhale as you lower. To exit, lower all the way down or press up into Upward Dog or Cobra.","breathCue":"Exhale to lower with control.","modifications":["Knees-chest-chin","Skip and go to puppy or child"],"avoidIf":["Shoulder impingement flare"],"commonMistakes":["Elbows winging out","Collapsing chest"],"alignmentCues":["Elbows hug ribs","Shoulders at elbow height"]},"flying-warrior":{"name":"Flying Warrior Pose","goodFor":"Builds mobility, strength, and awareness for Flying Warrior Pose.","instructions":"From Warrior III or a lunge, find a bind or arm variation that lifts into a flying shape if available — or stay in a strong Warrior III line. Soften the standing knee. To exit, step down with control."},"side-plank":{"name":"Side Plank","goodFor":"Lateral core strength and shoulder stability.","instructions":"From plank, shift onto the outer edge of one foot and stack or stagger the feet. Bottom arm stacks under the shoulder; top arm reaches up or to the hip. Hips lift; body in one long line. Soft gaze. To exit, return to plank or lower the knees."},"extended-side-plank":{"name":"Extended Side Plank","goodFor":"Advanced lateral-core and shoulder strength.","instructions":"From Side Plank, lift the top leg and/or reach the top arm overhead to open the side body. Keep the bottom shoulder stable. Soft gaze. To exit, lower the top leg and return to Side Plank or plank."},"inverted-staff":{"name":"Inverted Staff Pose","goodFor":"Builds mobility, strength, and awareness for Inverted Staff Pose.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Inverted Staff Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"little-thunderbolt":{"name":"Little Thunderbolt","goodFor":"Deep kneeling backbend.","instructions":"Come to the floor and set up Little Thunderbolt with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"tiger":{"name":"Tiger Pose","goodFor":"Spinal mobility and glute activation.","instructions":"Come to the floor and set up Tiger Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"upward-facing-dog":{"name":"Upward-Facing Dog Pose","goodFor":"Builds mobility, strength, and awareness for Upward-Facing Dog Pose.","instructions":"Lying face-down or from Chaturanga, press into the hands and straighten the arms to lift the chest. Tops of the feet press down; thighs lift off the mat. Roll the shoulders back; broaden the collarbones. Gaze soft forward or slightly up. Inhale to open. To exit, tuck the toes and lift the hips into Down Dog, or lower to the belly.","breathCue":"Inhale to open the chest; legs strong.","modifications":["Cobra with thighs down","Pad under hips"],"avoidIf":["Acute lumbar pain — prefer cobra"],"commonMistakes":["Shoulders shrugged","Feet lazy"],"alignmentCues":["Tops of feet press down","Thighs lift"]},"wheel":{"name":"Wheel Pose","goodFor":"Deep backbend strength and chest opening.","instructions":"Lie on your back, bend the knees, place hands by the ears with fingers toward the shoulders. Press into hands and feet to lift into an arch. Soften the neck; keep weight even. Breathe steadily — do not hold the breath. To exit, tuck the chin slightly and lower with control onto the shoulders then back.","breathCue":"Steady breath; never hold it to push harder.","modifications":["Stay in bridge","Hands on blocks"],"avoidIf":["Uncontrolled high blood pressure","Wrist injury","Pregnancy"]},"wild-thing":{"name":"Wild Thing","goodFor":"Heart opening with shoulder and hip strength.","instructions":"Come to the floor and set up Wild Thing with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"both-feet-behind-the-head-ii":{"name":"Both Feet Behind the Head II Pose","goodFor":"Builds mobility, strength, and awareness for Both Feet Behind the Head II Pose.","instructions":"From a seated position, bring both feet behind the head only with extreme mobility and prior preparation — never force. Soften the neck and jaw. To exit, release one foot at a time with the hands."},"chin-stand":{"name":"Chin Stand Pose","goodFor":"Builds mobility, strength, and awareness for Chin Stand Pose.","instructions":"Come to the floor and set up Chin Stand Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"crane":{"name":"Crane Pose","goodFor":"Builds mobility, strength, and awareness for Crane Pose.","instructions":"From a squat, plant the hands and place the knees high on the upper arms (Crow/Crane family). Lean forward, gaze ahead, and lift the feet. Round the back slightly; engage the core. To exit, lower the feet to a squat.","breathCue":"Short steady breaths; eyes soft forward.","modifications":["Feet on a block","One foot lifts"],"avoidIf":["Wrist pain"]},"crow":{"name":"Crow Pose","goodFor":"Arm balance strength and focus."},"deaf-mans":{"name":"Deaf Man’s Pose","goodFor":"Calming inversion variation; quieting forward fold upside down.","instructions":"Come to the floor and set up Deaf Man’s Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"eight-angle":{"name":"Eight Angle Pose","goodFor":"Builds mobility, strength, and awareness for Eight Angle Pose.","instructions":"From a seated twist or squat, hook one thigh high on the upper arm, plant the hands, and cross the ankles as you lift and twist. Core strong; gaze forward. To exit, lower the hips and untangle the legs."},"elbow-balance":{"name":"Elbow Balance Pose","goodFor":"Builds mobility, strength, and awareness for Elbow Balance Pose.","instructions":"Come to the floor and set up Elbow Balance Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"elephant-trunk":{"name":"Elephant Trunk Pose","goodFor":"Builds mobility, strength, and awareness for Elephant Trunk Pose.","instructions":"From a seated position, hook one leg over the upper arm (elephant trunk), plant the hands, and lift. Soften the neck. To exit, lower the hips and release the leg."},"firefly":{"name":"Firefly Pose","goodFor":"Arm-balance strength with hamstring engagement.","instructions":"From a squat, thread the shoulders under the thighs, plant the hands, and straighten the legs out to the sides as you lift. Soften the elbows slightly. Gaze forward. To exit, bend the knees and lower the feet."},"floating-stick":{"name":"Floating Stick Pose","goodFor":"Builds mobility, strength, and awareness for Floating Stick Pose.","instructions":"From a seated or plank-like arm support, engage the core and lift the legs into a stick-like line. Soften the neck. To exit, lower the hips or feet with control."},"flying-man":{"name":"Flying Man Pose","goodFor":"Builds mobility, strength, and awareness for Flying Man Pose.","instructions":"Come to the floor and set up Flying Man Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"revolved-flying-man":{"name":"Revolved Flying Man Pose","goodFor":"Builds mobility, strength, and awareness for Revolved Flying Man Pose.","instructions":"Come to the floor and set up Revolved Flying Man Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"two-legged-sage-koundinyas":{"name":"Two Legged Sage Koundinya\\\\","goodFor":"Builds mobility, strength, and awareness for Two Legged Sage Koundinya\\\\","instructions":"From a twisted arm-balance prep, plant the hands, hook both legs over one upper arm, and lean forward to lift. Gaze forward; elbows soft. To exit, lower the feet and untwist."},"side-crow":{"name":"Side Crow","goodFor":"Twisting arm balance strength and focus.","instructions":"From a twisted squat, plant both hands to the side of the legs and lean the knees onto the upper arms. Gaze forward and lift the feet. Engage the core. To exit, lower the feet with control."},"forearm-balance":{"name":"Forearm Balance","goodFor":"Inversion strength and shoulder stability.","instructions":"Use Forearm Balance as a linking shape between poses. Set the hands and feet with clear alignment, then move with the breath rather than momentum. Keep the core lightly engaged and the neck long. Stay only as long as the breath stays smooth. To exit, flow into the next pose in your sequence, or drop the knees to rest."},"dragonfly":{"name":"Dragonfly  Pose","goodFor":"Builds mobility, strength, and awareness for Dragonfly  Pose.","instructions":"From a wide-legged seat or arm balance prep, support the legs on the upper arms and lean forward to lift. Soften the neck. To exit, lower with control and shake out the legs."},"handstand":{"name":"Handstand","goodFor":"Full inversion strength and proprioception.","instructions":"From Down Dog or a lunge at the wall, place the hands shoulder-width and kick or float one leg up, then the other. Arms strong; gaze between the hands or slightly forward. Soften the jaw. To exit, lower one foot at a time with control."},"supported-headstand":{"name":"Supported Headstand","goodFor":"Classic inversion for focus and upper-body strength.","instructions":"Come to the floor and set up Supported Headstand with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"tripod-headstand":{"name":"Tripod Headstand Pose","goodFor":"Builds mobility, strength, and awareness for Tripod Headstand Pose.","instructions":"Come to the floor and set up Tripod Headstand Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"flying-lizard":{"name":"Flying Lizard Pose","goodFor":"Builds mobility, strength, and awareness for Flying Lizard Pose.","instructions":"Come to the floor and set up Flying Lizard Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"peacock":{"name":"Peacock Pose","goodFor":"Intense core and wrist strength.","instructions":"Come to the floor and set up Peacock Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"pendant":{"name":"Pendant Pose","goodFor":"Builds mobility, strength, and awareness for Pendant Pose.","instructions":"Begin standing with steady feet and a soft gaze. Arrange the body into Pendant Pose: place the feet first, then the hands or arms, then lengthen the spine. Soften any joint that feels compressed; keep the breath easy. Hold at a depth you can sustain without gripping the jaw. To exit, reverse the entry with control and return to mountain or a forward fold before continuing."},"flying-pigeon":{"name":"Flying Pigeon Pose","goodFor":"Builds mobility, strength, and awareness for Flying Pigeon Pose.","instructions":"Come to the floor and set up Flying Pigeon Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"plow":{"name":"Plow Pose","goodFor":"Posterior stretch and calming inversion.","instructions":"From lying or Shoulderstand prep, lift the legs overhead and lower the toes toward the floor behind you if available. Support the back with the hands or keep arms on the floor. Soften the neck — never turn the head. To exit, roll down slowly with bent knees, hands supporting.","breathCue":"Soft breath; exit if pressure in the head/neck.","modifications":["Feet to a chair","Knees bent"],"avoidIf":["Neck injury","Glaucoma"]},"rooster":{"name":"Rooster Pose","goodFor":"Builds mobility, strength, and awareness for Rooster Pose.","instructions":"From a lotus or bound-leg seat, plant the hands and attempt to lift the body (rooster balance). Soften the neck; only lift as high as stable. To exit, lower the hips carefully and unfold the legs."},"scorpion":{"name":"Scorpion Pose","goodFor":"Builds mobility, strength, and awareness for Scorpion Pose.","instructions":"Come to the floor and set up Scorpion Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"shoulder-pressing":{"name":"Shoulder Pressing Pose","goodFor":"Builds mobility, strength, and awareness for Shoulder Pressing Pose.","instructions":"Come to the floor and set up Shoulder Pressing Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"shoulder-stand-with-lotus-legs":{"name":"Shoulder Stand with Lotus Legs Pose","goodFor":"Builds mobility, strength, and awareness for Shoulder Stand with Lotus Legs Pose.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Shoulder Stand with Lotus Legs Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"supported-shoulder-stand":{"name":"Supported Shoulder Stand Pose","goodFor":"Builds mobility, strength, and awareness for Supported Shoulder Stand Pose.","instructions":"Come to the floor and set up Supported Shoulder Stand Pose with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing.","breathCue":"Soft free breath; never turn the head.","modifications":["Legs up the wall instead"],"avoidIf":["Neck injury","Glaucoma","Menstruation (traditional caution)","Pregnancy"]},"bound-revolved-chair":{"name":"Bound Revolved Chair Pose","goodFor":"Builds mobility, strength, and awareness for Bound Revolved Chair Pose.","instructions":"From Chair, bring hands to the heart and twist the torso to one side, hooking the opposite elbow outside the thigh. Press the arm into the leg to deepen the twist; lengthen the spine on each inhale. Soften the knees evenly. Gaze past the shoulder. To exit, untwist to center and straighten the legs."},"forward-fold":{"name":"Standing Forward Fold","goodFor":"Hamstring length, calming the nervous system, gentle inversion."},"halfway-lift":{"name":"Halfway Lift","goodFor":"Spinal length and preparing for folds or standing poses."},"warrior-1":{"name":"Warrior I","goodFor":"Hip opening, leg strength, and chest expansion."},"warrior-2":{"name":"Warrior II","goodFor":"Stamina, hip mobility, and shoulder endurance."},"warrior-3":{"name":"Warrior III","goodFor":"Balance, posterior-chain strength, and focus."},"reverse-warrior":{"name":"Reverse Warrior","goodFor":"Side stretch with continued lower-body strength.","instructions":"From Warrior II, keep the front knee bent and slide the back hand down the back leg. Reach the front arm up and slightly back, opening the side body. Soften the neck; gaze up only if comfortable. Front knee stays tracking over the ankle. To exit, return the torso upright to Warrior II.","breathCue":"Inhale lift the top arm; exhale keep front thigh strong.","modifications":["Hand on front thigh instead of back leg"]},"wide-forward-fold":{"name":"Wide-Legged Forward Fold","goodFor":"Inner-thigh and hamstring stretch; calming forward fold."},"standing-split":{"name":"Standing Split","goodFor":"Hamstring length, balance, and mild inversion."},"down-dog":{"name":"Downward-Facing Dog","goodFor":"Full-body reset, shoulder strength, and posterior-chain stretch."},"up-dog":{"name":"Upward-Facing Dog","goodFor":"Back strength, chest opening, and counterpose to folds."},"chaturanga":{"name":"Four-Limbed Staff","goodFor":"Arm and core strength for vinyasa transitions."},"tabletop":{"name":"Tabletop","goodFor":"Neutral alignment base for floor work."},"thread-needle":{"name":"Thread the Needle","goodFor":"Upper-back release and gentle thoracic twist.","instructions":"From table, slide one arm under the opposite armpit, palm up, resting on the shoulder and ear. The other hand stays planted or reaches up/around. Soften into the twist. Breathe into the upper back. To exit, press into the supporting hand and untwist to table.","breathCue":"Exhale thread the arm; inhale space between blades."},"locust":{"name":"Locust Pose","goodFor":"Posterior-chain strength for posture."},"supine-twist":{"name":"Supine Twist","goodFor":"Spinal mobility and low-back release."},"knees-to-chest":{"name":"Knees to Chest","goodFor":"Low-back relief and digestion support."},"figure-four":{"name":"Reclined Figure Four","goodFor":"Outer-hip and IT-band region release.","instructions":"Lie on your back. Cross one ankle over the opposite thigh. Thread the hands behind the uncrossed thigh (or over the shin) and draw the legs in. Keep the head and shoulders relaxed on the mat. Soften the jaw. To exit, release the legs and switch, or plant the feet.","breathCue":"Exhale soften the hips toward the floor.","modifications":["Head on a pillow"]},"butterfly":{"name":"Butterfly Pose","goodFor":"Inner-thigh stretch and hip mobility."},"seated-forward-fold":{"name":"Seated Forward Fold","goodFor":"Hamstring length and calming forward fold."},"wide-seated-fold":{"name":"Wide-Angle Seated Fold","goodFor":"Wide-leg flexibility and inner-thigh stretch."},"seated-twist":{"name":"Seated Twist","goodFor":"Spinal mobility and digestive massage."},"legs-up-wall":{"name":"Legs-Up-the-Wall","goodFor":"Recovery, circulation, and calming inversion."},"reclining-butterfly":{"name":"Reclining Butterfly","goodFor":"Restorative hip opening and stress relief.","instructions":"Lie on your back. Bring the soles of the feet together and let the knees fall open. Support outer thighs with blankets if needed. Arms rest by the sides. Soften the belly. To exit, use the hands to close the knees and roll to one side."},"easy-seat":{"name":"Easy Seat","goodFor":"Meditation seat and gentle hip opening."},"half-split":{"name":"Half Splits","goodFor":"Targeted hamstring stretch with knee support."},"shoulder-stand":{"name":"Shoulder Stand","goodFor":"Inversion benefits, thyroid stimulation tradition, core strength."},"revolved-chair":{"name":"Revolved Chair","goodFor":"Leg strength with detoxifying twist."},"supine-hand-to-toe":{"name":"Supine Hand to Big Toe","goodFor":"Controlled hamstring stretch with pelvic stability."},"crescent":{"name":"Crescent Lunge","goodFor":"Hip-flexor stretch with energizing lift."},"hand-to-big-toe":{"name":"Standing Hand to Big Toe","goodFor":"Hamstring length with balance and focus."},"extended-hand-to-big-toe":{"name":"Extended Hand to Big Toe","goodFor":"Outer-hip opening with single-leg balance."},"head-to-knee":{"name":"Head to Knee","goodFor":"Asymmetric hamstring stretch and calming fold."},"marichi":{"name":"Sage Marichi Pose","goodFor":"Forward fold with a shoulder bind stretch."},"marichi-twist":{"name":"Sage Marichi Twist","goodFor":"Seated twist for spinal mobility and digestion."},"archer":{"name":"Archer Pose","goodFor":"Hip and hamstring opening with a seated bind."},"crow-kakasana":{"name":"Crow (Kakasana)","goodFor":"Foundational arm balance."},"locust-arms":{"name":"Locust Arms Forward","goodFor":"Posterior-chain strength with shoulder endurance."},"wide-forward-side":{"name":"Side Wide-Legged Fold","goodFor":"Hamstring stretch with lateral body length."},"revolved-wide-fold":{"name":"Revolved Wide-Legged Fold","goodFor":"Wide-leg fold with a twist."},"upward-plank-prep":{"name":"Upward Plank Prep","goodFor":"Builds toward full Upward Plank.","instructions":"Come to the floor and set up Upward Plank Prep with even pressure in the hands, knees, or hips. Lengthen the spine before adding effort. Move into the shape on an exhale if it closes the body, or an inhale if it opens the chest. Keep the jaw and shoulders soft. To exit, lower with control and pause in a neutral rest before continuing."},"sage-marichis-ii":{"name":"Sage Marichi's II Pose","goodFor":"Hip opening with a forward fold and bind.","description":"One foot in half lotus, the other foot planted. Fold forward, wrapping the arm around the bent shin.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Sage Marichi's II Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"sage-marichis-iii":{"name":"Sage Marichi's III Pose","goodFor":"Seated twist for spinal mobility and digestion.","description":"One leg extended, the other foot planted. Twist toward the bent knee, hugging it with the opposite arm.","instructions":"Sit with one foot flat and the other leg extended or half-lotus. Hug the bent knee and twist toward it, hooking the opposite arm. Lengthen on the inhale; twist on the exhale. To exit, untwist and switch.","breathCue":"Exhale to twist; inhale to lengthen the spine.","modifications":["Keep the extended leg soft","Hand behind for leverage"],"avoidIf":["Late pregnancy — skip deep closed twists"]},"sage-marichis-iv":{"name":"Sage Marichi's IV Pose","goodFor":"Advanced seated twist and hip opener.","description":"Combine half lotus with a deep seated twist and optional bind. Move slowly and keep both sit bones grounding.","instructions":"Sit tall on the sit bones — use a folded blanket if the low back rounds. Arrange the legs for Sage Marichi's IV Pose, then lengthen the spine on an inhale before folding, twisting, or binding. Soften the shoulders away from the ears. Breathe steadily; ease out of any sharp sensation. To exit, release binds first, then uncross or straighten the legs slowly."},"cross-legged-forward-fold":{"name":"Cross-Legged Forward Fold","goodFor":"Gentle hip and back release from a seated fold (Easy Seat without the fold stays as Easy Pose).","description":"Sit in a comfortable cross-legged position. Lengthen your spine as you inhale, then hinge at the hips to fold forward, walking your hands out in front of you."},"knee-lift":{"name":"Knee Lift","goodFor":"Simple standing balance and hip flexion warm-up.","description":"Stand with feet together. Lift one foot off the floor. Lock your hands around your shin as you lift your knee to your chest. Switch sides."},"kneeling":{"name":"Kneeling","goodFor":"Neutral transition between floor and standing work.","description":"Kneel on the mat. Keep your back straight and roll your shoulders away from your ears. Hands on the hips."},"morning-stretch":{"name":"Morning Stretch","goodFor":"Gentle wake-up lengthening before or after floor work.","description":"Lie on your back. Place your arms on the mat above your head. Gently stretch your hands and fingers away from your feet and toes."},"opened-knee-lift":{"name":"Opened Knee Lift","goodFor":"Balance with a mild standing hip opener.","description":"Stand with feet together. Lift one foot off the floor so your knee is in line with your hips. Grab that knee with the same-side hand and gently take the leg outwards. Place the opposite hand on the hip. Switch sides."},"reclined-bent-knees":{"name":"Reclined Bent Knees","goodFor":"Neutral rest that eases the low back more than flat-leg Corpse for many bodies.","description":"Lie flat on your back. Bend your knees and place the soles of your feet on the floor hip-width apart."},"seated-cactus-arms":{"name":"Seated Cactus Arms","goodFor":"Seated chest and shoulder opener; pairs well with breath work.","description":"Sit tall with feet grounded or legs crossed. Raise arms to cactus, elbows at 90°, forearms vertical. Draw shoulders down as you broaden the chest."},"standing-back-bend":{"name":"Standing Back Bend","goodFor":"Gentle standing heart-opener and posture reset.","description":"Stand tall with feet grounded. Place your hands together and reach overhead. Lift your chest and gently arch through your upper back while keeping your core engaged and legs strong."},"standing-side-bend":{"name":"Standing Side Bend","goodFor":"Standing lateral stretch for the side body and breath space.","description":"Stand tall with feet hip-width apart. Raise both arms overhead and interlace your fingers. Slowly bend your upper body to one side, keeping your chest open and your hips square. Switch sides."}}`),t={"sun-a-foundation":{name:`Sun Salutation Foundation`,description:`Standard warm-up arc: mountain → fold → plank → dog cycles to build heat safely before standing work.`,focus:`Vinyasa · heat`},"peak-warrior":{name:`Peak: Warrior Strength`,description:`Peak-pose method: warm spine → sun-salute heat → warriors as peak → hip openers → twist → savasana.`,focus:`Peak pose · warriors`},"peak-wheel":{name:`Peak: Wheel Backbend`,description:`Progressive backbend prep (peak-pose pattern): hip flexors → gentle extension → bridge → wheel → counterfolds.`,focus:`Peak pose · wheel`},"peak-crow":{name:`Peak: Crow Arm Balance`,description:`Wrist/core prep then crow peak (common arm-balance class template), with soft floor integration.`,focus:`Peak pose · crow`},"standing-flow":{name:`Standing Flow Classic`,description:`Classic mid-class standing block: warriors, triangle, balance, wide folds — the heart of many vinyasa classes.`,focus:`Standing · balance`},"yin-hips":{name:`Yin: Hips & Groin`,description:`Modern yin template: few shapes, long holds (use Gentle/45s+), rebound between poses, long savasana.`,focus:`Yin · hips`},"yin-spine":{name:`Yin: Spine & Side Body`,description:`Yin spinal focus with gentle twists and side bends, ending in extended rest.`,focus:`Yin · spine`},"restorative-evening":{name:`Restorative Evening`,description:`Nervous-system downshift: supported shapes, legs up, minimal effort — common evening best practice.`,focus:`Restorative`},"mobility-morning":{name:`Morning Mobility`,description:`Short arrive → joint warm-up → easy standing → floor cool-down (popular short daily practice arc).`,focus:`Full body · gentle`},"hamstring-flow":{name:`Hamstring Focus Flow`,description:`Progressive back-line release (reclined stretch → dog → half-split → pyramid → seated fold). Longer seated holds; no filler repeats.`,focus:`Hamstrings`},"hip-opener-modern":{name:`Hip Opener (Modern)`,description:`Contemporary hip-focused class: lunges and pigeons mid-practice after warm-up, yin-ish finish.`,focus:`Hips`},"core-and-twist":{name:`Core & Twist`,description:`Heat + core + twists (popular athletic class theme), then neutralizing folds.`,focus:`Core`},"inversion-prep":{name:`Inversion Prep`,description:`Shoulder/hamstring prep into supported inversions — never skip cool-down after upside-down work.`,focus:`Inversions`},"full-vinyasa-arc":{name:`Full Vinyasa Arc (60-style)`,description:`Condensed 60-minute class arc from teacher guides: center → warm → stand → peak balance → hips → savasana.`,focus:`Full body`},"gentle-floor":{name:`Gentle Floor Flow`,description:`Floor-heavy recovery day with light standing balance.`,focus:`Full body · gentle`},"sun-b-heat":{name:`Sun Salutation B Heat`,description:`Classic Sun B building block used in Ashtanga/vinyasa: chair + Warrior I cycles before standing work.`,focus:`Vinyasa · heat`},"peak-half-moon":{name:`Peak: Half Moon`,description:`Yoga Journal peak-pose method for Ardha Chandrasana: triangle/side-body prep → balance → soft landing.`,focus:`Peak pose · balance`},"peak-revolved-triangle":{name:`Peak: Revolved Triangle`,description:`Peak template for Parivrtta Trikonasana: hamstring + twist components separately, then combine.`,focus:`Peak pose · twist`},"shoulders-and-heart":{name:`Shoulders & Heart Open`,description:`Body-part sequencing (YJ approach): gradual shoulder opening and heart extension with counterfolds.`,focus:`Shoulders · chest`},"grounding-root":{name:`Grounding Strength`,description:`Modern grounding class arc: heavy standing shapes, balance, then hips and long savasana.`,focus:`Standing · grounding`},"desk-reset":{name:`Desk Reset (15-style)`,description:`Popular short daily reset: neck/shoulder/hip openers without a long standing peak — a compact micro-practice pattern.`,focus:`Mobility · short`}},n=JSON.parse(`{"breath":{"title":"Breath — when and how","summary":"Match effort to breath: natural for restore, steady for strength, and never hold to push through.","body":"Breath is the metronome of practice. When the breath is easy, the nervous system tends to settle; when it stalls or becomes ragged, the pose is usually too intense for today. Treat breath as information, not as something to conquer. If you need one rule to carry onto every mat, make it this: keep the breath continuous and soften the face before you deepen anything else.\\n\\nNatural breath means soft nose breathing with an easy belly and ribs. Use it in restorative and yin, at the start of class, and whenever you feel rushed or self-critical. There is nothing “less yogic” about an ordinary inhale. YogApp’s free breath pattern leaves you alone on purpose so you can find your own pace without chasing a cue.\\n\\nA steady or ujjayi-style breath adds a light throat constriction that can warm and focus a standing or strength sequence. Keep it gentle — never strain the neck or force a loud ocean sound. Link movement to breath in simple ways: inhale to lift, lengthen, or open; exhale to fold, twist, or settle. In sun salutations that pairing becomes a rhythm you can trust even when the mind wanders.\\n\\nAvoid holding the breath to “push through” a hard pose, forced retention in twists or inversions, and gasping through the mouth when you could simply shorten the hold. If breath falls apart, exit with control, rest, and return when you can speak in full sentences again. Enable announce-breath cues in Settings if soft inhale and exhale reminders help you stay present during longer holds."},"safety":{"title":"Safety & red flags","summary":"Stretchy or warm sensation is usually fine; sharp, electrical, dizzy, or breath-breaking signals mean back off.","body":"This is general practice guidance, not medical advice — if you have injuries or conditions, ask a qualified teacher or clinician before pushing into new shapes.\\n\\nSensation that is stretchy, warm, or muscularly tired is usually workable. Sharp, electrical, dizzy, or nauseating signals mean back off. Pain that makes you hold your breath, clench your jaw, or lose the ability to leave the pose with control is not a badge of progress. Leaving early is skill. Resting in child’s pose or savasana is still practice.\\n\\nStop or modify if you feel sharp joint pain, especially in knees, wrists, neck, or low back; numbness or tingling that intensifies; shooting pain down a limb; dizziness; vision changes; or shortness of breath beyond ordinary effort. If you cannot keep a steady breath, the intensity is too high for this moment. Come down, breathe, and choose a simpler shape.\\n\\nCommon caution zones deserve extra patience. For wrists in planks and arm balances, try fists, forearms, or skip the pose. For the neck in shoulderstand, plow, or deep camel, never turn the head — prefer legs-up-the-wall. For knees in lotus, hero, or deep pigeon, do not force; use a figure-four or a supported variation. For the lumbar in deep backbends, pad under the hips, bend the knees, or stay in bridge.\\n\\nOpen any pose in the library for Avoid and Modify notes. Props are not a consolation prize; they are tools that keep joints spacious while you build strength and awareness over time. When in doubt, choose the version you could repeat tomorrow without bracing against fear."},"sequencing":{"title":"How classes are built","summary":"Most modern classes follow a warm-up, peak, counterpose, and savasana arc that teachers learn in training.","body":"A well-built class feels like a story with a beginning, middle, and end. You arrive, you warm the body, you explore a focus, you neutralize, and you rest. Skipping the bookends — centering and savasana — is like editing the first and last pages of a novel: the middle still happens, but the integration does not.\\n\\nMost modern vinyasa classes follow a simple arc. Arrive and center with an easy seat, breath, and gentle spinal movement. Warm with cat-cow, downward dog, and sun salutations until the breath is awake and the joints feel oiled. Standing and peak work introduce the focus pose with preparation shapes that teach its parts — hips, shoulders, balance, or strength — without dumping you into the hardest version first.\\n\\nFloor work and counterposes follow: hips, folds, and twists that neutralize the peak. Twists after backbends, gentle folds after deep hip openers, and something that lets the nervous system downshift. Savasana is integration, not an optional nap. Even three quiet minutes help the practice settle into the body.\\n\\nWhen you build your own sessions, ask what the peak needs. A crow needs warm wrists, open hips, and core; a wheel needs thoracic mobility and strong legs; a long yin hold needs heat already soft enough that you can stay without bracing. YogApp built-ins follow this logic — Sun A Foundation, Peak Warrior, Wheel, Crow, Yin, Restorative — and the Wizard picks from that menu using time of day and your history so you are not reinventing the arc from scratch every morning."},"effort":{"title":"When to push harder","summary":"Progress one variable at a time — range, hold time, or load — and let steady breath be the green light.","body":"Effort in yoga is not the same as maxing out at the gym. The useful question is not “Can I force this?” but “Can I stay kind and clear while I explore a little further?” Progress one variable at a time: range of motion, hold time, or load. Changing all three at once is how form collapses and resentment creeps in.\\n\\nGreen lights that you may deepen include a steady breath, a soft face and jaw, joints that feel spacious rather than pinched, stable form for several breaths, and the ability to leave the pose with control. If those are present, you can explore a half-inch more, a few more seconds, or a slightly stronger variation — then reassess.\\n\\nYellow and red lights mean ease off. Breath that holds or becomes ragged, shaking that collapses alignment, ego driving the pose (“I should be able to…”), or pain that is sharp or neural are all invitations to simplify. There will be other days. The practice that lasts is the one that leaves you curious rather than broken.\\n\\nAfter a session, log effort on the summary screen when you can. Patterns matter more than any single heroic hour. The Wizard uses your history to suggest shorter days after gaps, which is a quiet kindness to future-you. Strength grows in recovery as much as in the hold; treat rest days as part of the training, not as failure to show up."},"savasana-hardest":{"title":"Why savasana is the hardest pose","summary":"Lying still asks the mind to stop performing — and that can feel harder than any balance or backbend.","body":"People laugh when teachers say savasana is the hardest pose, then spend the final minutes twitching, planning dinner, or peeking at the clock. The joke lands because it is true. After forty minutes of doing, the nervous system is asked to undo — and undoing has no scoreboard.\\n\\nIn asana we can hide inside effort. Muscle burn feels productive. A deep fold looks like achievement. Savasana offers nowhere to perform. You lie down, arrange the limbs so nothing needs gripping, and meet whatever the mind brings: restlessness, boredom, the urge to skip “just this once.” That meeting is the pose.\\n\\nHard does not mean grim. Soften the eyes under closed lids. Let the tongue rest. If thoughts arrive, notice them the way you notice clouds — present, moving, not a problem to solve on the mat. If you need a bridge into stillness, take a longer child’s pose or a supported reclined twist first, then settle. Three honest minutes beat ten minutes of fidgeting while pretending you are fine.\\n\\nSkipping savasana to rush into the day teaches the body that practice ends in urgency. Keeping it, even briefly, teaches that effort has a landing place. If you only change one habit this month, protect the final rest. Leave your phone outside the room and give the practice a chance to finish speaking."},"phones-off-mat":{"title":"Phones off the mat","summary":"Notifications pull attention out of the body; a phone-free mat is a small boundary with outsized calm.","body":"A phone on the mat is a door left open. Even face-down, it hums with unfinished conversations and the possibility of interruption. Yoga already asks for enough — breath, balance, kindness — without competing against a glowing rectangle that thrives on partial attention.\\n\\nYou do not need a monastery. Put the phone in another room, or at least in a bag with notifications off. If you use an app for timers or music, set it before you begin and place the device where you cannot see the lock screen. Treat the session like a short appointment with yourself that other people can wait for.\\n\\nHome practice is especially vulnerable. The kitchen ping, the work Slack, the urge to film a pose for later. Each glance resets the nervous system toward vigilance. Studio walls help because the social contract is clearer; at home you have to write that contract yourself. A simple ritual helps: roll the mat, silence the phone, take three breaths before the first movement.\\n\\nThis is not purity theater. Life is full of legitimate reasons to stay reachable. It is a vote for depth over fragmentation for twenty or forty minutes. When the practice ends, the messages will still be there. You might answer them from a slightly wider place — which is, quietly, the point."},"beginner-ego":{"title":"Beginner ego and the comparison trap","summary":"Wanting to “keep up” is human; mistaking someone else’s shape for your homework is how joy leaks out.","body":"Every room has a silent ranking system if you let it: who balances longer, whose heels touch the floor, who floats into crow without a second thought. Beginner ego is not vanity alone — it is the tender wish to belong, mixed with the fear of being seen as behind. That mix can push people into shapes their joints are not ready for.\\n\\nComparison steals information. Your neighbor’s handstand says almost nothing about your wrists, sleep, stress, or decade of desk work. What looks effortless may be years of practice, lucky proportions, or a body that has not yet met its limits. Your job is not to match their silhouette. Your job is to notice your breath and choose the version you can leave with dignity.\\n\\nTeachers can accidentally feed the trap by praising only the deepest expression. Good rooms celebrate modifications out loud. If you are new, claim the block, the knee down, the shorter hold. That is not lesser yoga; it is accurate yoga. Accuracy builds trust, and trust is what lets you deepen later without bracing against shame.\\n\\nWhen ego spikes — “I should be able to by now” — pause and rename the goal. Today’s success might be staying for the whole class, keeping the neck soft in a backbend, or leaving before pain arrives. Progress often looks sideways: more ease in a familiar pose, less rush between shapes, a kinder inner narrator. Those wins do not photograph well. They travel well."},"home-vs-studio":{"title":"Home practice vs studio","summary":"Studios offer community and structure; home offers flexibility — most lasting practices borrow from both.","body":"Studio practice hands you a container: a time, a teacher, other bodies breathing nearby. That container makes showing up easier on days when motivation is thin. You borrow someone else’s sequencing, music, and pacing, and you leave the laundry in another room. For many people, that external structure is how a habit begins.\\n\\nHome practice offers a different gift. You can practice at dawn in pajamas, shorten a session when life is loud, and explore poses without an audience. You also meet every excuse personally: the email, the snack, the sudden need to reorganize a drawer. Without a plan, home practice dissolves into stretching while thinking about work.\\n\\nA durable approach often mixes both. Use studio or live classes to learn alignment, discover new sequences, and feel the lift of shared effort. Use home days for consistency — even fifteen focused minutes — so practice does not depend on a schedule or a commute. Write a tiny ritual: same corner, same first three poses, phone away, timer set.\\n\\nIf home feels lonely, add light structure from tools you trust: a familiar routine, breath cues, or a short peak you already know. If studio feels performative, choose restorative or beginner rooms and stand near the back until the nervous system settles. Neither setting is morally superior. The question is which mix keeps you practicing with curiosity instead of dread."},"roots-of-asana":{"title":"Roots of asana","summary":"Classical yoga emphasized stillness and meditation; the athletic asana vocabulary many know is largely modern.","body":"When people say “yoga,” they often picture a sequence of standing postures, balances, and flows. That image is recent. Classical texts such as the Yoga Sutras mention asana mainly as a steady, comfortable seat for meditation — a posture that supports stillness rather than a catalog of athletic shapes. The body was prepared so the mind could settle, not displayed as the main event.\\n\\nMedieval hatha traditions expanded physical practice: purification, breath control, and postures meant to steady energy for deeper work. Even then, the lists of poses were smaller than a modern studio schedule, and the goal remained transformation of attention and vitality, not calorie burn or Instagram lines. Context matters: these practices lived inside lineages, vows, and philosophies that rarely fit a lunch-break class.\\n\\nThe twentieth century changed the map. Teachers in India — among them figures associated with Mysore and related lineages — systematized dynamic asana, often influenced by gymnastics, wrestling, and military drill as well as older hatha. Photography, print manuals, and later global travel carried those systems abroad. What many Western students inherited was a vigorous postural yoga that still used Sanskrit names and older frames, but prioritized strength, flexibility, and sequenced movement.\\n\\nKnowing this history does not make your downward dog less real. It invites humility. Asana can be devotion, therapy, sport, or moving meditation depending on how you hold it. When you practice today, you stand in a long conversation — some pages ancient, some barely a century old. Honor the seat and the sweat both, and remember that stillness was the original destination."},"hatha-vs-vinyasa":{"title":"Hatha vs vinyasa","summary":"Hatha often means slower, held postures; vinyasa links breath to movement — both can be strong or gentle.","body":"In studio marketing, “hatha” and “vinyasa” get used as shorthand for slow versus flowing. The words are older and wider than that. Hatha historically pointed to the broader physical and energetic path — postures, breath, and related practices — not a single class style. On a modern schedule, a hatha class usually means poses held for several breaths with more time for alignment and less continuous movement.\\n\\nVinyasa, in contemporary usage, emphasizes linking breath to movement and transitioning between shapes. Sun salutations are the familiar engine. Classes can be athletic or moderate; the common thread is rhythm. Some lineages use precise counts; others leave timing more open. Either way, the nervous system tends to stay warmer and more mobile than in a long-hold room.\\n\\nNeither label guarantees intensity. A “gentle vinyasa” can be softer than a demanding hatha class stacked with deep stands and long balances. Read the description, ask the teacher, and notice your breath after ten minutes. If you need grounding, longer holds and fewer transitions may help. If you need to shake off mental fog, a steady flow with clear inhale-exhale links may serve better.\\n\\nFor home practice, you can borrow both. Warm with a short flow, then settle into held standing or floor work. Or reverse it: explore a peak pose slowly, then use a few breath-linked transitions to integrate. The useful distinction is not brand loyalty — it is whether today’s body wants rhythm, stillness, or a conversation between the two."},"yin-origins":{"title":"Where yin yoga comes from","summary":"Yin’s long floor holds draw on Taoist ideas and modern teaching; it complements, rather than replaces, yang styles.","body":"Yin yoga, as popularized in the late twentieth century, asks you to settle into shapes for minutes at a time, usually on the floor, with muscles soft rather than engaged for show. The aim is to stress connective tissue gently and give the nervous system a long exhale. It looks quiet from the outside and can feel intensely honest on the inside.\\n\\nTeachers associated with the style drew on Taoist yin-yang language and on ideas about fascial and energetic pathways, weaving them with asana shapes familiar from hatha. Exact historical claims vary by teacher, and scholars debate how directly modern yin maps onto older Chinese practices. For practitioners, the lived method matters more than the brochure: arrive, find an appropriate edge, stay, breathe, and leave without yanking.\\n\\nYin is not a contest to suffer longest. Props, padding, and early exits are wise. Sharp joint pain is still a stop sign. Because holds are long, small misalignments add up — support the knees, keep the neck easy, and choose variations that let muscles melt instead of grip. Heat beforehand can help, but many people practice yin cool and still benefit.\\n\\nThink of yin as a complement to yang styles like vinyasa or power classes. Strength and heat build capacity; long passive holds teach patience and recovery. A week that includes both often feels more complete than doubling down on only intensity. If your mind races in stillness, shorten the holds and keep the principle: less muscular effort, more listening."},"sanskrit-naming":{"title":"Sanskrit naming on the mat","summary":"Pose names carry images and lineage; learning a few roots makes the room feel less like a secret code.","body":"Sanskrit pose names can feel like a wall if you are new. Teachers alternate between “downward-facing dog” and adho mukha svanasana, and the brain scrambles. The names are not there to gatekeep. They are compact images and lineage markers — a shared map that travels across languages when English translations diverge.\\n\\nMany names are built from parts you can learn like Lego. Adho means downward; mukha means face; svana means dog. Tri means three; kona means angle — hence triangle. Ardha means half; chandra means moon. Once a handful of roots click, unfamiliar names stop being noise and start being clues about shape and direction.\\n\\nYou do not need fluency to practice well. English cues are enough for safety and breath. Still, tasting the Sanskrit can deepen respect for the tradition’s texture, especially when a name points to a myth, animal, or sage. Say what you can pronounce kindly; correct yourself without shame. Teachers differ on accent and exact forms — consistency inside a lineage matters more than winning a pronunciation contest.\\n\\nIf memorization overwhelms you, pick five poses you love and learn both names. Use them in your home practice so the sound attaches to sensation. Over months the glossary grows without flashcards. The goal is not to impress the room. The goal is to feel at home in a vocabulary that has carried these shapes across generations."},"eight-limbs":{"title":"Eight limbs overview","summary":"Asana is one limb among eight — ethics, breath, senses, concentration, and meditation complete the map.","body":"Patanjali’s eight-limbed path is a classic map many teachers still reference. It does not demand that every gym-class warrior sequence become a philosophy seminar. It does remind us that postures sit inside a wider project: how we treat others, how we treat ourselves, how we breathe, and how we steady attention.\\n\\nThe first two limbs, yama and niyama, sketch ethical and personal disciplines — honesty, non-harming, contentment, and related commitments interpreted differently across eras. Asana, the third, is the embodied seat or posture. Pranayama works with breath and energy. Pratyahara turns the senses inward so attention is less yanked by every sound and itch.\\n\\nThe final three — dharana, dhyana, and samadhi — describe concentration, meditation, and deep absorption. Few modern classes claim to deliver the last limb in forty-five minutes, and that humility is healthy. What they can offer is practice in returning: notice distraction, come back to breath or sensation, repeat without scolding.\\n\\nOn a practical Tuesday, the limbs show up quietly. Choosing not to force a painful knee is non-harming. Showing up when you said you would is discipline. Softening the gaze in balance is a taste of sensory quiet. You do not have to master the list. Let it widen the frame so asana is more than shapes — a training ground for attention and care that leaves the mat with you."},"modern-yoga-west":{"title":"Modern yoga in the West","summary":"Travel, books, and studios transformed postural yoga into a global wellness culture with many dialects.","body":"Yoga did not arrive in the West as a single package. Lectures, books, visiting teachers, and later immigration carried philosophies, breath practices, and postural systems into Europe and North America across the twentieth century. Some audiences wanted mysticism; others wanted health, flexibility, or calm. The marketplace answered with many dialects under one popular name.\\n\\nBy the late twentieth century, yoga studios, teacher trainings, and media turned asana into a recognizable lifestyle. Branding, fashion, and fitness culture amplified certain vigorous styles while quieter practices continued in smaller rooms. Commercial success brought access and also distortion: spiritual language used as marketing, thinness mistaken for advancement, and lineages flattened into trends.\\n\\nCritique and renewal grew alongside popularity. Teachers and scholars asked harder questions about cultural appropriation, accessibility, injury, and who feels welcome in the room. Trauma-informed language, body-positive spaces, chair yoga, and online classes widened the door. None of that erases harm automatically — it is ongoing work — but it shows the tradition adapting in public.\\n\\nFor a practitioner today, “Western yoga” is less a verdict than a landscape. You can seek lineage depth, therapeutic care, athletic challenge, or simple weekly movement. Choose teachers who cite sources honestly, prioritize safety, and leave room for questions. The global story is still being written every time someone rolls out a mat with curiosity instead of a costume."},"props-history":{"title":"A short history of props","summary":"Blocks, straps, and blankets moved from inventive supports to standard tools that make asana more accessible.","body":"Props look modern — colorful foam blocks, cotton straps, bolsters stacked like furniture — but the impulse is old: use what helps the body find a sustainable shape. Ropes, walls, and household objects have long stood in when a pose asked for length or leverage the unaided body could not offer yet.\\n\\nIn the twentieth century, teachers such as B.K.S. Iyengar made systematic prop use famous: bricks, belts, chairs, and blankets to refine alignment and include students who could not approximate a photograph. What some rooms once treated as remedial became, in that approach, intelligent design. Accessibility and precision shared the same toolkit.\\n\\nToday most studios keep a prop wall without apology. A block under the hand in triangle is not a demotion; it is a way to keep the spine long while hamstrings catch up. A strap in a forward fold teaches the shape of the pose without rounding into strain. Bolsters in restorative practice let the nervous system believe it is safe to rest.\\n\\nIf ego whispers that props are for beginners, answer with longevity. Joints prefer spaciousness. Strength still builds when the foundation is honest. Keep a block and strap near your home mat the way a kitchen keeps a cutting board — ordinary tools for better work. The advanced move is choosing the support that lets you breathe."}}`),r=JSON.parse(`{"calm-arrive":{"title":"Arriver et s'installer","summary":"Atterrissage en douceur dans le présent. Libérez la journée et trouvez votre place.","script":["Accueillir.","Prenez un moment pour arriver.","Trouvez un siège confortable ou allongez-vous si vous vous sentez mieux.","Laissez vos mains se reposer.","Laissez vos yeux se fermer ou adoucissez votre regard.","Remarquez que vous êtes ici.","Rien à réparer pour le moment.","Rien à compléter.","Inspirez lentement par le nez.","Et une expiration plus longue.","Encore. Inspirez doucement.","Expirez doucement.","Sentez le poids de votre corps soutenu.","Le sol, la chaise, la terre qui vous retient.","Si les pensées s’égarent, ce n’est pas grave.","Remarquez simplement et revenez à cette respiration.","Inhaler. Arriver.","Exhaler. Régler.","Encore une respiration facile.","Lorsque vous êtes prêt, ouvrez les yeux.","Emportez ce calme avec vous."]},"body-scan":{"title":"Scanner corporel","summary":"Attention douce de la couronne aux orteils. Avis sans fixation.","script":["Nous scannerons doucement le corps.","Allongez-vous ou asseyez-vous facilement.","Fermez les yeux si vous vous sentez en sécurité.","Commencez par le sommet de la tête.","Remarquez toute sensation là-bas. Chaleur. Fraîcheur. Rien du tout.","Pas besoin de le changer. Remarquez simplement.","Déplacez-vous doucement vers le front et les yeux.","Laissez les petits muscles autour des yeux s’adoucir.","Sentez la mâchoire. Desserrez si vous le pouvez.","Langue reposant légèrement.","Épaules. Sont-ils levés ? Laissez-les tomber un peu.","Les bras lourds. Mains ouvertes ou douces.","La poitrine monte et descend avec le souffle.","Ventre mou. Pas de forçage.","Hanches et bassin au repos.","Cuisses. Genoux. Bas des jambes.","Pieds. Semelles touchant le sol ou le tapis.","Maintenant, ressentez le corps tout entier comme un seul champ de conscience.","Le souffle le traverse.","Si un point tendu apparaît, envoyez-y une aimable expiration.","Restez pendant trois respirations tranquilles.","Lorsque vous êtes prêt, remuez les doigts et les orteils.","Ouvrez les yeux. Revenez doucement."]},"breath-awareness":{"title":"Conscience de la respiration","summary":"Ancrage à la respiration naturelle. Comptez les cycles doux sans forcer.","script":["Installez-vous dans une posture stable.","Dos haut mais non rigide.","Portez votre attention sur la respiration telle qu’elle est déjà.","Ne le changez pas encore. Regardez simplement.","Ressentez la fraîcheur de l’inspiration au niveau des narines.","Ressentez la chaleur de l’expiration.","Ou remarquez la montée et la descente du ventre.","Choisissez un endroit pour retenir votre attention.","Lorsque l’esprit s’égare, revenez gentiment.","Aucun jugement. Revenez simplement.","Maintenant, si cela vous semble facile, comptez les cycles doux.","Inhaler. Un.","Exhaler. Un.","Inhaler. Deux.","Exhaler. Deux.","Continuez jusqu'à cinq, puis recommencez à une heure.","Si vous perdez le compte, recommencez avec bienveillance.","Le retour est la pratique.","Laissez la respiration être naturelle. Aucune contrainte.","Encore quelques cycles en silence.","Relâchez le décompte.","Restez en conscience ouverte pendant un moment.","Lorsque vous êtes prêt, ouvrez les yeux."]},"loving-kindness":{"title":"Bienveillance Lite","summary":"De courtes phrases de bonne volonté pour vous-même et pour quelqu'un qui vous est cher.","script":["Asseyez-vous confortablement. Adoucit le visage.","Placez une main sur le cœur si cela peut aider.","Nous vous proposerons des phrases simples de gentillesse.","D’abord envers vous-même.","Répétez silencieusement après moi, ou écoutez simplement.","Puis-je être en sécurité.","Puis-je aller bien.","Puis-je être à l'aise.","Répétez-les lentement.","Puis-je être en sécurité.","Puis-je aller bien.","Puis-je être à l'aise.","Si cela semble difficile, ce n'est pas grave. Restez avec le souhait lui-même.","Maintenant, pensez à quelqu’un dont il est facile de se soucier.","Un ami, un animal de compagnie, un gentil étranger.","Imaginez-les brièvement.","Puissiez-vous être en sécurité.","Puissiez-vous aller bien.","Puissiez-vous être à l'aise.","Une fois de plus.","Puissiez-vous être en sécurité.","Puissiez-vous aller bien.","Puissiez-vous être à l'aise.","Ressentez toute la chaleur qui surgit. Ou reposez-vous simplement sur les mots.","Revenez à votre propre souffle.","Merci d'avoir pratiqué.","Ouvrez doucement les yeux."]},"evening-wind-down":{"title":"Soirée de détente","summary":"Libérez le jour. Ralentissez le système nerveux avant de dormir.","script":["Cette pratique est pour la fin de la journée.","Baissez les lumières si vous le pouvez.","Allongez-vous ou inclinez-vous avec un soutien.","Que la journée soit terminée, même si l'esprit énumère encore les tâches.","Vous pouvez les déposer pour l'instant.","Inspirez doucement en comptant jusqu’à quatre.","Expirez en comptant jusqu’à six.","Encore. Quatre entrées. Six sorties.","Des expirations plus longues indiquent au corps qu'il peut se reposer en toute sécurité.","Recherchez les tensions restantes sur le visage.","Adoucit le sourcil. Adoucit la mâchoire.","Éloignez les épaules des oreilles.","Imaginez la journée se déposer comme de la poussière après une brise.","Ce qui est arrivé est arrivé.","Ce qui reste peut attendre jusqu'au matin.","Sentez le matelas ou le sol vous retenir.","Respirez plus calmement. Corps plus lourd.","Si le sommeil vient, laissez-le.","Sinon, reposez-vous quand même dans cette douceur.","Trois autres respirations lentes.","Dans. Dehors.","Dans. Dehors.","Dans. Dehors.","Bonne nuit au jour. Paix à la nuit."]},"anxiety-soft-landing":{"title":"Anxiété Atterrissage en douceur","summary":"Ancré à travers les sens. Une courte réinitialisation lorsque les nerfs sont à vif.","script":["Si vous vous sentez activé ou inquiet, vous êtes le bienvenu ici.","Vous n’avez pas encore besoin de vous sentir calme.","Suivez simplement.","Plantez les deux pieds sur le sol si vous le pouvez.","Ressentez le contact. Talons. Boules des pieds. Orteils.","Appuyez doucement. Remarquez le recul du sol.","Nommez cinq choses que vous pouvez voir.","Tranquillement. Pas de précipitation.","Nommez quatre choses que vous pouvez toucher.","Vêtements. Chaise. Air sur la peau.","Nommez trois sons, proches ou lointains.","Nommez deux parfums ou remarquez simplement l’air.","Nommez un goût ou une sensation en bouche.","Vous êtes ici. Dans ce corps. Dans cette pièce.","Maintenant, inspirez pendant quatre.","Tenez doucement pendant deux.","Sortie pour six heures.","Encore une fois si tu veux.","Placez une main sur la poitrine ou le ventre.","Sentez le mouvement sous votre main.","L'anxiété peut encore être présente. C'est permis.","Vous avez donné au système nerveux un atterrissage plus doux.","Respirez encore une fois.","Lorsque vous êtes prêt, ouvrez les yeux et continuez votre journée."]},"forest-clearing-5":{"title":"Déboisement","summary":"Arrivez dans le corps, puis reposez-vous dans une clairière boisée ensoleillée.","script":["Accueillir.","Prenez un siège confortable ou allongez-vous si vous vous sentez mieux.","Laissez vos mains se reposer.","Laissez vos yeux se fermer ou adoucissez votre regard.","Remarquez le poids de votre corps.","Inspirez lentement par le nez.","Et une expiration plus longue et plus facile.","Encore. Inspirez doucement.","Expirez doucement.","Si les pensées s’égarent, ce n’est pas grave. Revenez à la respiration.","Imaginez maintenant un chemin sous une litière de feuilles molles.","Vous marchez sans hâte dans une forêt tranquille.","Une lumière tachetée se déplace sur vos avant-bras.","Ressentez la douce chaleur du soleil partout où il trouve votre peau.","Une fraîcheur fraîche parcourt la brise entre les arbres.","Sentez la terre verte, l’écorce et une humidité minérale propre.","Le chemin débouche sur une petite clairière.","La mousse amortit une bûche tombée. Vous êtes assis.","La lumière du soleil s'accumule au centre comme de l'or tranquille.","Ressentez cette chaleur sur votre visage, lentement et bienveillante.","Une brise effleure vos cheveux et rafraîchit vos tempes.","Le chant des oiseaux arrive de loin, puis s'efface.","Votre souffle correspond au silence des feuilles.","Inspirez la fraîcheur. Expirez toute hâte restante.","Remarquez à quel point le sol est sûr sous vous.","Comme le ciel semble large au-dessus de la canopée.","Un coléoptère traverse sans hâte une parcelle d’écorce ensoleillée.","Vous n'avez nulle part où être sauf ici.","La chaleur s'accumule à nouveau sur vos paupières fermées.","L'air frais se glisse sous votre col comme une main bienveillante.","Restez avec la chaleur sur vos joues.","Restez avec l’air frais sur vos lèvres pendant que vous expirez.","Cette clairière ne demande rien. Cela vous tient simplement.","Laissez une respiration supplémentaire voyager jusqu’au ventre.","Et repartir, doux comme les feuilles.","Promenez-vous lentement autour du bord de la clairière.","Fougère. Ombre. Un champignon pâle à la base d'une souche.","Tout est vivant parce que vous n'êtes pas pressé.","Ressentez la chaleur du soleil là où elle atterrit sur le genou.","Ressentez la fraîcheur de la brise là où elle glisse dans la gorge.","Tu pourrais rester ici tout l'après-midi. Pour l’instant, quelques respirations suffisent.","Maintenant, reposez-vous sur la respiration pendant un petit moment.","Inspirez lentement.","Expirez lentement.","Inhaler.","Exhaler.","Ressentez la chaleur partout où le corps est chaud.","Ressentez la fraîcheur partout où l'air est frais.","Inhaler.","Exhaler.","Nulle part où aller. Rien à réparer.","Inhaler.","Exhaler.","Reposez-vous ici pour quelques respirations tranquilles.","Sachez que vous pouvez revenir à cet endroit à tout moment.","Lorsque vous êtes prêt, approfondissez la respiration.","Remuez les doigts et les orteils.","Ouvrez doucement les yeux.","Emportez un peu de cette paix avec vous."]},"lakeside-dawn-5":{"title":"Aube au bord du lac","summary":"Respirez en conscience dans une matinée calme de lac, de chaleur et d'air frais.","script":["Accueillir.","Prenez un siège confortable ou allongez-vous si vous vous sentez mieux.","Laissez vos mains se reposer.","Laissez vos yeux se fermer ou adoucissez votre regard.","Remarquez le poids de votre corps.","Inspirez lentement par le nez.","Et une expiration plus longue et plus facile.","Encore. Inspirez doucement.","Expirez doucement.","Si les pensées s’égarent, ce n’est pas grave. Revenez à la respiration.","Imaginez-vous au bord d'un lac immobile à l'aube.","L'eau recèle un ciel argenté pâle.","L'air frais effleure vos joues d'une fraîcheur propre.","Un doux ruban de soleil commence à réchauffer vos épaules.","Sentez cette chaleur se propager lentement dans votre dos.","Vous vous rapprochez. Le sable mou cède sous vos pieds.","Trempez le bout de vos doigts dans l'eau. Cool. Clair.","Les ondulations se propagent vers l’extérieur et disparaissent.","La brise sent légèrement les plantes aquatiques et le matin.","Écouter. Presque rien. Un oiseau lointain. Votre propre souffle.","Sit on a smooth stone warmed just enough by the rising light.","Ressentez la chaleur tranquille de la pierre sous vous.","Sentez la fraîcheur de l'air entrer dans vos poumons.","Le lac reflète le rose tendre et l’or.","Vous regardez la lumière se déplacer sur la surface comme une respiration lente.","Un poisson se lève, les anneaux s'élargissent, puis le miroir revient.","Chaleur sur vos paupières fermées.","De la fraîcheur sur le dos des mains.","Quelque part au loin, une corde de bateau fait tic-tac contre du bois.","Puis à nouveau le silence, large et bienveillant.","Inspirez la fraîcheur du matin. Expirez dans l’eau libre.","La paix s'installe dans la façon dont la brume se lève de l'eau – doucement, complètement.","Vous avez le droit de prendre de la place dans ce calme.","Encore un souffle de l'aube.","Regardez à nouveau le chemin argenté de la lumière sur l'eau.","Suivez-le avec des yeux doux vers la rive opposée.","Les arbres là-bas sont bleus avec la distance et la brume matinale.","La chaleur grandit un peu sur vos épaules à mesure que le soleil se lève.","La brise reste fraîche – née du lac et propre.","Laissez cette fraîcheur rincer l’esprit comme la lumière rince la surface.","Asseyez-vous ensemble pendant trois autres bouffées de chaleur et d’air frais.","Maintenant, reposez-vous sur la respiration pendant un petit moment.","Inspirez lentement.","Expirez lentement.","Inhaler.","Exhaler.","Ressentez la chaleur partout où le corps est chaud.","Ressentez la fraîcheur partout où l'air est frais.","Inhaler.","Exhaler.","Nulle part où aller. Rien à réparer.","Inhaler.","Exhaler.","Reposez-vous ici pour quelques respirations tranquilles.","Sachez que vous pouvez revenir à cet endroit à tout moment.","Lorsque vous êtes prêt, approfondissez la respiration.","Remuez les doigts et les orteils.","Ouvrez doucement les yeux.","Emportez un peu de cette paix avec vous."]},"meadow-breeze-5":{"title":"Prairie de montagne","summary":"Installez-vous, puis allongez-vous dans l'herbe chaude sous une légère brise alpine.","script":["Accueillir.","Prenez un siège confortable ou allongez-vous si vous vous sentez mieux.","Laissez vos mains se reposer.","Laissez vos yeux se fermer ou adoucissez votre regard.","Notice the weight of your body being held.","Inspirez lentement par le nez.","Et une expiration plus longue et plus facile.","Encore. Inspirez doucement.","Expirez doucement.","Si les pensées s’égarent, ce n’est pas grave. Revenez à la respiration.","Imaginez une vaste prairie de montagne en fin de matinée.","Les herbes hautes se balancent en vagues faciles.","Le soleil est chaud sans être vif.","Ressentez-le sur le sommet de votre tête, gentil et stable.","Une brise fraîche se déplace dans l’herbe et trouve votre visage.","It smells of wildflowers and sun-dried earth.","Vous marchez lentement, le bout des doigts effleurant les têtes de graines.","Chatouillement doux. Son doux.","Les papillons se lèvent et s’installent à nouveau sans se presser.","Vous trouvez un endroit pour vous allonger dans l'herbe.","La terre tient sur toute votre longueur.","Chaleur sur le devant. Ombre de sol fraîche à vos côtés.","La brise va et vient comme une marée amicale.","Inhale freshness. Expirez à ciel ouvert.","Un nuage glisse un instant sur le soleil.","Fraîcheur. Puis la chaleur revient sur votre visage.","Remarquez à quel point le silence est grand.","Comme toute inquiétude semble minime dans ce vaste domaine.","Vos mains reposent dans l'herbe. De minuscules tiges pressent gentiment.","Restez avec la chaleur du soleil sur vos yeux fermés.","Restez avec la douce pression de l’herbe contre vos bras.","Vous êtes autorisé à rester ainsi.","Laissez la prairie vous respirer pendant encore quelques cycles.","Faites rouler votre attention depuis la couronne chaude de la tête","à travers un visage doux, une gorge douce,","dans un coffre qui s'élève facilement à ciel ouvert.","La brise pénètre à l'intérieur de vos poignets.","Cool. Vivant. Amical.","Quelque part, les abeilles travaillent sans urgence.","Leur bourdonnement est une autre sorte de silence.","Restez jusqu'à ce que la chaleur et la fraîcheur ne forment qu'un seul tissu.","Maintenant, reposez-vous sur la respiration pendant un petit moment.","Inspirez lentement.","Expirez lentement.","Inhaler.","Exhale.","Ressentez la chaleur partout où le corps est chaud.","Ressentez la fraîcheur partout où l'air est frais.","Inhaler.","Exhaler.","Nulle part où aller. Rien à réparer.","Inhaler.","Exhaler.","Reposez-vous ici pour quelques respirations tranquilles.","Sachez que vous pouvez revenir à cet endroit à tout moment.","Lorsque vous êtes prêt, approfondissez la respiration.","Remuez les doigts et les orteils.","Ouvrez doucement les yeux.","Emportez un peu de cette paix avec vous."]},"cove-shore-5":{"title":"Crique abritée","summary":"Corps et respiration, puis une crique tranquille de plage, de soleil et d'air salin.","script":["Accueillir.","Prenez un siège confortable ou allongez-vous si vous vous sentez mieux.","Laissez vos mains se reposer.","Laissez vos yeux se fermer ou adoucissez votre regard.","Remarquez le poids de votre corps.","Inspirez lentement par le nez.","Et une expiration plus longue et plus facile.","Encore. Inspirez doucement.","Expirez doucement.","Si les pensées s’égarent, ce n’est pas grave. Revenez à la respiration.","Imaginez-vous arriver dans une crique abritée.","Les falaises se courbent autour de sable pâle et doux.","La mer se déplace par vagues basses et patientes.","Un doux soleil réchauffe le haut de vos épaules.","Une brise salée rafraîchit vos lèvres et vos paupières.","Sentez la fraîcheur de cet air remplir votre poitrine.","Marchez jusqu'à la ligne de flottaison. Le sable mouillé épouse vos pieds.","La mousse fraîche touche vos chevilles et glisse.","The rhythm is simple. Arrive. Soften. Leave.","Asseyez-vous là où le sable sec est chaud sous vous.","Appuyez-vous sur vos mains. Ressentez la chaleur granuleuse.","Écoutez le silence et la ruée de la crique.","Sentez le sel, le soleil et la pierre propre.","De la chaleur sur votre peau. De la fraîcheur à chaque inspiration.","Au loin, la lumière scintille comme un rire silencieux.","Vous n'avez pas besoin de le poursuivre. C'est déjà là.","Une vague atteint plus loin, refroidit vos orteils, puis recule.","Le sable chaud récupère vos pieds.","Laissez votre respiration suivre les vagues – entrez lentement, expirez plus longtemps.","La paix est la crique elle-même. Vous êtes à l'intérieur.","Portez votre attention sur la chaleur entre vos omoplates.","Et sur l’air frais et salé du bout du nez.","Tracez la ligne de la falaise avec une douce imagination.","Pierre réchauffée par jour. Ombre fraîche dans les plis.","Un bassin de marée à proximité abrite un petit monde clair.","Vous n’avez pas besoin de vous pencher. Savoir que c’est là suffit.","Une autre vague. Chevilles fraîches. Sable chaud. Souffle doux.","La crique continue d'offrir la même gentillesse simple.","Recevez-le une fois de plus avant de partir.","Maintenant, reposez-vous sur la respiration pendant un petit moment.","Inspirez lentement.","Expirez lentement.","Inhaler.","Exhaler.","Ressentez la chaleur partout où le corps est chaud.","Ressentez la fraîcheur partout où l'air est frais.","Inhaler.","Exhaler.","Nulle part où aller. Rien à réparer.","Inhaler.","Exhaler.","Reposez-vous ici pour quelques respirations tranquilles.","Sachez que vous pouvez revenir à cet endroit à tout moment.","Lorsque vous êtes prêt, approfondissez la respiration.","Remuez les doigts et les orteils.","Ouvrez doucement les yeux.","Emportez un peu de cette paix avec vous."]},"garden-dusk-5":{"title":"Jardin au crépuscule","summary":"Arrivée en douceur dans un jardin clos rafraîchissant après une journée chaude.","script":["Accueillir.","Prenez un siège confortable ou allongez-vous si vous vous sentez mieux.","Laissez vos mains se reposer.","Laissez vos yeux se fermer ou adoucissez votre regard.","Remarquez le poids de votre corps.","Inspirez lentement par le nez.","Et une expiration plus longue et plus facile.","Encore. Inspirez doucement.","Expirez doucement.","Si les pensées s’égarent, ce n’est pas grave. Revenez à la respiration.","Imaginez un jardin clos et tranquille au doux crépuscule.","Les chemins de pierre retiennent la dernière chaleur de la journée.","Ressentez cette douce chaleur à travers la plante de vos pieds.","La lavande et les roses du soir dégagent un parfum apaisant.","Une brise fraîche glisse sur le mur et vous rafraîchit le cou.","L'air est frais après un après-midi chaud.","Vous marchez lentement entre des haies taillées douces comme le souffle.","Vos doigts effleurent les feuilles qui retiennent encore le soleil.","Chaud. Lisse. Vivant.","Un banc en bois attend sous un arbre tranquille.","Vous êtes assis. Le bois est agréablement chaud contre votre dos.","Au-dessus, le ciel devient lavande et rose.","Les oiseaux s'installent. Le jardin devient silencieux.","Sentez la chaleur s'estomper doucement de la pierre et du bois.","Sentez la fraîcheur rafraîchissante du soir sur votre visage.","Inspirez le parfum et le calme.","Expirez le jour où vous êtes arrivé.","Un papillon traverse la dernière lumière dorée.","Rien ici n’est urgent. Tout suffit.","Reposez-vous dans cette suffisance.","Laissez votre ventre se ramollir dans l’air du crépuscule.","Laissez votre prochaine respiration être la plus calme de la journée.","Parcourez une boucle lente du chemin avant de terminer.","Des pierres chaudes refroidissant sous les pieds.","Des haies libérant le parfum emmagasiné de la journée.","La brise a maintenant une touche du soir : fraîche, presque douce.","Faites une pause au portail sans l’ouvrir encore.","Sentez à quel point le calme s'est installé dans vos épaules.","Portez le silence du jardin comme une petite lanterne vers l’intérieur.","Maintenant, reposez-vous sur la respiration pendant un petit moment.","Inspirez lentement.","Expirez lentement.","Inhaler.","Exhaler.","Ressentez la chaleur partout où le corps est chaud.","Feel coolness wherever the air is cool.","Inhaler.","Exhaler.","Nulle part où aller. Rien à réparer.","Inhaler.","Exhaler.","Reposez-vous ici pour quelques respirations tranquilles.","Sachez que vous pouvez revenir à cet endroit à tout moment.","When you are ready, deepen the breath.","Remuez les doigts et les orteils.","Ouvrez doucement les yeux.","Emportez un peu de cette paix avec vous."]},"forest-path-10":{"title":"Chemin de la forêt profonde","summary":"Voyage plus long à travers une vieille forêt vers la mousse, le ruisseau et le calme.","script":["Accueillir.","Trouvez une posture qui ne vous demande rien.","Asseyez-vous ou allongez-vous avec le soutien dont vous avez besoin.","Laissez vos mains ouvertes ou douces.","Laissez vos yeux se fermer ou gardez un regard doux.","Ressentez les endroits où votre corps rencontre le sol.","Les talons, les ischions, l'arrière de la tête ou la longueur de la colonne vertébrale.","Rien à retenir pour le moment.","Inspirez lentement par le nez.","Sentez la fraîcheur de l’air arriver.","Et expirez encore un peu.","Ressentez la chaleur de l’expiration qui part.","Encore. Inspirez doucement.","Expirez sans hâte.","Laissez les épaules baisser un peu.","Laissez la mâchoire se desserrer.","Que le ventre soit mou.","Restez avec trois respirations calmes, telles quelles.","Inhaler. Arriver.","Exhaler. Régler.","Si l’esprit s’égare, remarquez-le gentiment et revenez à cette respiration.","Commencez maintenant une lente promenade dans une vieille forêt.","Le chemin est doux avec des aiguilles et des feuilles mortes.","Chaque pas fait un bruit sourd, puis le silence revient.","La lumière du soleil se faufile à travers les hautes branches en rubans chauds.","Sentez une tache de soleil sur votre avant-bras – une douce chaleur soudaine.","Puis ombragez à nouveau, frais et vert.","Une brise fait bouger la verrière. L'air frais trouve votre visage.","Smell resin, damp soil, and the clean sweetness of moss.","Pause. Placez une paume sur l'écorce rugueuse.","Sentez le calme de l’arbre entrer dans votre main.","Continuez plus profondément. Les bruits du monde extérieur disparaissent.","Quelque part, un ruisseau parle en petites syllabes lumineuses.","You follow until water appears between stones.","Agenouillez-vous. Trempez vos mains. Clarté cool.","Splash a little on your wrists. Freshness wakes the skin.","Asseyez-vous sur un rocher plat chauffé par une étroite colonne de soleil.","Feel that warmth in your sit bones and the backs of your thighs.","Sentez le souffle frais du ruisseau contre vos tibias.","Les oiseaux crient une fois, puis quittent à nouveau le calme.","Respirez la fraîcheur de la forêt.","Expirez dans les troncs des patients autour de vous.","Remarquez comment vos épaules sont tombées sans qu'on vous le demande.","Comment la mâchoire s'adoucit quand il n'y a nulle part où aller.","Levez-vous lorsque vous êtes prêt et marchez un peu plus loin.","Les fougères effleurent vos mollets du bout des doigts verts et frais.","Une clairière s’ouvre – ronde comme un souffle retenu.","Allongez-vous sur la mousse profonde.","La terre reçoit entièrement votre poids.","Chaleur du soleil filtré sur votre visage.","Fraîcheur de la mousse le long de votre colonne vertébrale.","La brise arrive, part, revient.","Restez avec le sentiment d'être détenu par un lieu vivant.","Sûr. Calme. Appartenance sans effort.","Comptez ici cinq respirations lentes, chacune plus douce.","Remarquez à nouveau le parfum – vert, humide, honnête.","Remarquez à nouveau le son – presque aucun, et c'est largement suffisant.","Si une pensée apparaît, laissez-la dériver comme une feuille sur le ruisseau.","Retrouvez la chaleur sur la peau partout où le soleil vous trouve.","Retournez à la fraîcheur à l'ombre entre ces rubans chauds.","Vous avez marché suffisamment loin vers l’intérieur.","Laissez trois respirations lentes sceller cela dans le corps.","Avant de partir, placez-vous de nouveau au bord du ruisseau.","Regardez l’eau claire tresser autour des pierres.","L'air frais s'élève de la surface en mouvement.","Une lumière chaude trouve toujours une bande de votre avant-bras.","Tasse d'eau et mouillez le front si vous le souhaitez - en imagination, frais et gentil.","La forêt n'applaudit pas. Cela continue simplement.","Cette continuité est un enseignant.","Parcourez le chemin vers l’extérieur en faisant quelques pas tranquilles dans l’esprit.","Aiguilles sous les pieds. Son doux. Retour en douceur.","Pourtant, la paix de la clairière reste dans la poitrine comme le soleil emmagasiné.","Ressentez-le là – la chaleur derrière le sternum.","Sentez la fraîcheur encore au niveau des narines.","Vous pouvez apporter les deux dans des pièces ordinaires.","Un dernier regard à travers les branches vers une pièce de monnaie du ciel.","Assez.","Maintenant, laissez l'histoire se reposer et restez avec la sensation.","Respirez la fraîcheur de ce lieu.","Expirez dans sa chaleur et sa tranquillité.","Inhaler.","Exhaler.","Encore. Inspirez doucement.","Expirez plus longtemps.","Ressentez le corps retenu par le sol de ce monde imaginé.","Inhaler.","Exhaler.","Si les pensées s'égarent, revenez à la chaleur sur la peau.","Ou pour rafraîchir l'air au niveau du nez.","Inhaler.","Exhaler.","Inhaler.","Exhaler.","Rester. Adoucir. Continuer.","Inhaler.","Exhaler.","Encore un cycle facile.","Inhaler.","Exhaler.","Attardez-vous dans cette sensation pendant quelques respirations supplémentaires.","Chaleur. Douceur. Assez.","Vous pouvez revenir à cet endroit quand vous en avez besoin.","Il vit dans votre attention, pas seulement dans votre imagination.","Commencez à approfondir la respiration.","Ressentez à nouveau la pièce autour de vous.","Remuez les doigts. Adoucir les orteils.","Lorsque vous êtes prêt, ouvrez les yeux.","Respirez encore une fois.","Portez ce calme dans tout ce qui va suivre."]},"lake-wander-10":{"title":"Lake Shore Wander","summary":"A full lakeside walk of warm stone, cool water, and open sky.","script":["Welcome.","Find a posture that asks nothing of you.","Sit, or lie down, with whatever support you need.","Let your hands rest open or soft.","Allow your eyes to close, or keep a soft gaze.","Feel the places where your body meets the ground.","The heels, the sit bones, the back of the head, or the length of the spine.","Nothing to hold up right now.","Take a slow breath in through the nose.","Feel the coolness of the air arriving.","And breathe out a little longer.","Feel the warmth of the exhale leaving.","Again. Soft inhale.","Unhurried exhale.","Let the shoulders drop a fraction.","Let the jaw unclench.","Let the belly be soft.","Stay with three quiet breaths, just as they are.","Inhale. Arrive.","Exhale. Settle.","If the mind wanders, notice it kindly, and come back to this breath.","Imagine waking beside a wide quiet lake.","Morning light lies soft on the water.","Cool air touches your cheeks with a clean freshness.","The first sun warms the tops of your feet.","You begin a slow walk along the shore.","Sand and small smooth stones shift gently underfoot.","Each step is a quiet conversation with the ground.","A breeze comes off the water — fresh, lightly cool.","It lifts the hair at your temples.","Smell cedar, wet stones, and open morning.","Watch a heron stand in the shallows, perfectly still.","You match that stillness for a few breaths.","Warmth grows on your shoulders as the sun climbs.","Find a sunlit boulder and sit.","Feel heat stored in the stone rising into your body.","Feel the fresher air moving across your lips with each inhale.","The lake’s surface wrinkles, then goes glass again.","Light trembles there like quiet joy.","Continue around a curve of shore into a little bay.","Reeds whisper. Water ticks softly against wood.","An old dock stretches out. You walk to the end.","Sit with feet dangling above cool water.","Sun on your back. Breeze on your shins.","Dip a toe. Gentle chill. A smile you do not need to show.","Lie back on the warm boards.","Hear water under you. Sky above you.","Your breath becomes as wide as the lake.","Inhale freshness. Exhale into endless blue.","Nothing to solve. Only this warmth, this air, this peace.","Feel the dock’s heat along your spine.","Feel a cooler ribbon of air whenever the breeze turns.","A dragonfly stitches the air and is gone.","Stay until the feeling sinks into muscle and bone.","If the mind lists tasks, set them on the far shore for now.","They can wait. The lake is not waiting for anything.","One hand on the belly. Rise. Fall.","Warmth under the palm of the other hand on wood.","Rest in this double holding — body and place.","Stand and walk a little farther in imagination.","Pebbles click softly. Water brightens near a fallen branch.","Sun finds the back of your neck with friendly heat.","Shade from a willow cools your eyelids for a few steps.","Alternating warmth and freshness becomes a walking prayer.","No words required. Only sensation and breath.","Find a patch of warm sand and sit facing open water.","Let the eyes go soft on the horizon line.","Inhale the lake’s cool perfume.","Exhale toward the distant hills.","Whatever you carried here can rest on the shore beside you.","It does not need carrying in the water.","Stay until the next three breaths feel complete on their own.","Now let the story rest, and stay with sensation.","Inhale the freshness of this place.","Exhale into its warmth and quiet.","Inhale.","Exhale.","Again. Soft inhale.","Longer exhale.","Feel the body held by the ground of this imagined world.","Inhale.","Exhale.","If thoughts wander, return to warmth on the skin.","Or to cool air at the nose.","Inhale.","Exhale.","Inhale.","Exhale.","Stay. Soften. Continue.","Inhale.","Exhale.","One more easy cycle.","Inhale.","Exhale.","Linger in this feeling for a few more breaths.","Warmth. Softness. Enoughness.","You can return to this place whenever you need it.","It lives in your attention, not only in imagination.","Begin to deepen the breath.","Feel the room around you again.","Wiggle the fingers. Soften the toes.","When you are ready, open your eyes.","Take one more easy breath.","Carry this calm into whatever comes next."]},"coastal-walk-10":{"title":"Coastal Path","summary":"Cliff path to beach — sun, salt breeze, and tide-paced breath.","script":["Welcome.","Find a posture that asks nothing of you.","Sit, or lie down, with whatever support you need.","Let your hands rest open or soft.","Allow your eyes to close, or keep a soft gaze.","Feel the places where your body meets the ground.","The heels, the sit bones, the back of the head, or the length of the spine.","Nothing to hold up right now.","Take a slow breath in through the nose.","Feel the coolness of the air arriving.","And breathe out a little longer.","Feel the warmth of the exhale leaving.","Again. Soft inhale.","Unhurried exhale.","Let the shoulders drop a fraction.","Let the jaw unclench.","Let the belly be soft.","Stay with three quiet breaths, just as they are.","Inhale. Arrive.","Exhale. Settle.","If the mind wanders, notice it kindly, and come back to this breath.","See a coastal path along low cliffs.","The ocean breathes below in long, steady rolls.","Sunlight warms the crown of your head and the bridge of your nose.","A salt breeze cools your eyelids with bright freshness.","Smell the sea — mineral, clean, awake.","You walk slowly. Grasses lean inland in the wind.","Feel sun on one cheek, cool air on the other.","That contrast is itself a kind of calm.","A wooden stair leads down toward a hidden beach.","Each step is sure. Your hand rests on a weathered rail.","Warm wood under your palm.","At the bottom, sand receives your feet like a soft yes.","Walk to where waves write and erase white lines.","Cool water folds over your ankles.","Warm sand higher on the shore waits when you step back.","Sit. Dig your hands into sun-heated grains.","Feel that dry warmth against cool damp sand beneath.","Watch light shatter across open water.","Breathe in the freshness of the breeze.","Breathe out any tightness still held in the ribs.","A gull cries once and becomes part of the hush.","Lie back. Close your eyes.","Warmth across your front. Cool earth-shadow at your sides.","The tide’s rhythm coaches your heart toward ease.","You are small in the best way — held by something vast and kind.","Stay with the warmth of the sun on your closed eyes.","Stay with the cool kiss of spray on your skin when the wind turns.","Peace is not elsewhere. It is this shore, this breath, this body.","Dig your heels a little deeper into warm sand.","Feel how the earth answers with steady support.","Breathe in salt freshness to the bottom of the lungs.","Breathe out anything that has been bracing for impact.","There is no impact here. Only arrival after arrival of waves.","Let five breaths ride that same patient rhythm.","Then rest in the afterglow of sun on skin.","Rise and walk the waterline a short way.","Left foot cool and wet. Right foot warm and dry. Then switch.","The body learns contrast as comfort, not conflict.","Pick up a smooth stone warmed by light.","Feel its heat in the palm. Its density. Its quiet.","Set it down with thanks — no need to keep it.","The keeping is inward.","Look out past the breakers to calmer color.","Breathe as if you could taste blue.","Fresh breeze. Warm cheek. Soft belly.","Let the next inhale be the deepest of the practice.","Let the exhale empty without force.","The cove, the cliff, the path home — all wait without pressure.","Now let the story rest, and stay with sensation.","Inhale the freshness of this place.","Exhale into its warmth and quiet.","Inhale.","Exhale.","Again. Soft inhale.","Longer exhale.","Feel the body held by the ground of this imagined world.","Inhale.","Exhale.","If thoughts wander, return to warmth on the skin.","Or to cool air at the nose.","Inhale.","Exhale.","Inhale.","Exhale.","Stay. Soften. Continue.","Inhale.","Exhale.","One more easy cycle.","Inhale.","Exhale.","Linger in this feeling for a few more breaths.","Warmth. Softness. Enoughness.","You can return to this place whenever you need it.","It lives in your attention, not only in imagination.","Begin to deepen the breath.","Feel the room around you again.","Wiggle the fingers. Soften the toes.","When you are ready, open your eyes.","Take one more easy breath.","Carry this calm into whatever comes next."]},"canyon-gold-10":{"title":"Golden Canyon","summary":"Warm stone and fresh canyon air in late-day gold light.","script":["Welcome.","Find a posture that asks nothing of you.","Sit, or lie down, with whatever support you need.","Let your hands rest open or soft.","Allow your eyes to close, or keep a soft gaze.","Feel the places where your body meets the ground.","The heels, the sit bones, the back of the head, or the length of the spine.","Nothing to hold up right now.","Take a slow breath in through the nose.","Feel the coolness of the air arriving.","And breathe out a little longer.","Feel the warmth of the exhale leaving.","Again. Soft inhale.","Unhurried exhale.","Let the shoulders drop a fraction.","Let the jaw unclench.","Let the belly be soft.","Stay with three quiet breaths, just as they are.","Inhale. Arrive.","Exhale. Settle.","If the mind wanders, notice it kindly, and come back to this breath.","Imagine a wide canyon painted in soft gold and rose.","It is late afternoon. The light is generous.","Warmth radiates from stone that has held the sun all day.","Feel that radiant heat on your shins and the backs of your hands.","A dry, fresh breeze moves down the canyon floor.","It cools your face without taking the comfort of the warmth.","You walk a sandy path between quiet walls.","Footsteps whisper. Echoes are soft, almost polite.","Smell sunbaked earth, sage, and clean dust.","Place your palm on smooth stone.","Feel stored daylight there — steady, patient heat.","A ribbon of shade offers coolness for a few steps.","Then sun again, warm across your shoulders like a shawl.","You come to a place where the canyon opens.","Sit on a flat rock still holding golden warmth.","Feel it rise through your seat and spine.","Feel the fresher air of altitude in every inhale.","Far above, a hawk turns slow circles without hurry.","You borrow that unhurried quality.","Breath long. Body heavy. Mind wide as the sky between walls.","Watch shadow climb the far cliff as the sun lowers.","Colors deepen. Warmth softens but does not vanish.","The breeze smells cooler now, evening-fresh.","Wrap your arms around yourself for a moment.","Warmth of your own body. Warmth of stone. Enough.","Lie back carefully and watch the first quiet star.","The canyon holds you the way a cupped hand holds water — gently, without spill.","Rest in that held feeling.","Notice the last heat rising from rock into the cooling air.","Notice how the breeze now smells of evening and dust and sage.","Your breath has slowed to match the wide quiet.","If tension remains in the brow, soften it in this gold light.","If the jaw is tight, let it hang loose as the hawk’s easy turn.","Stay for a few more cycles of warm stone and fresh air.","You are not late. You are here.","Walk a few more steps along warm sand between canyon walls.","Your shadow stretches long and unworried.","Place both palms on stone again.","Heat enters the hands like a blessing you do not have to earn.","The breeze combs coolness through your hair.","Sage scent. Dust scent. Sun scent.","Sit. Knees soft. Spine easy.","Watch color deepen from gold toward rose.","Warmth softens. Freshness increases. Balance remains.","This is how evenings teach the nervous system to downshift.","Borrow the lesson without effort.","Three breaths for the stone.","Three for the sky.","Three for the quiet animal of your own body, resting.","Now let the story rest, and stay with sensation.","Inhale the freshness of this place.","Exhale into its warmth and quiet.","Inhale.","Exhale.","Again. Soft inhale.","Longer exhale.","Feel the body held by the ground of this imagined world.","Inhale.","Exhale.","If thoughts wander, return to warmth on the skin.","Or to cool air at the nose.","Inhale.","Exhale.","Inhale.","Exhale.","Stay. Soften. Continue.","Inhale.","Exhale.","One more easy cycle.","Inhale.","Exhale.","Linger in this feeling for a few more breaths.","Warmth. Softness. Enoughness.","You can return to this place whenever you need it.","It lives in your attention, not only in imagination.","Begin to deepen the breath.","Feel the room around you again.","Wiggle the fingers. Soften the toes.","When you are ready, open your eyes.","Take one more easy breath.","Carry this calm into whatever comes next."]},"bamboo-garden-10":{"title":"Bamboo Garden","summary":"After-rain garden walk of cool freshness and soft returning sun.","script":["Welcome.","Find a posture that asks nothing of you.","Sit, or lie down, with whatever support you need.","Let your hands rest open or soft.","Allow your eyes to close, or keep a soft gaze.","Feel the places where your body meets the ground.","The heels, the sit bones, the back of the head, or the length of the spine.","Nothing to hold up right now.","Take a slow breath in through the nose.","Feel the coolness of the air arriving.","And breathe out a little longer.","Feel the warmth of the exhale leaving.","Again. Soft inhale.","Unhurried exhale.","Let the shoulders drop a fraction.","Let the jaw unclench.","Let the belly be soft.","Stay with three quiet breaths, just as they are.","Inhale. Arrive.","Exhale. Settle.","If the mind wanders, notice it kindly, and come back to this breath.","Picture a bamboo garden after rain.","Stone is dark and clean. Leaves shine.","Cool freshness fills the air like a soft bell.","A break in the clouds lets sun through.","Feel sudden gentle warmth on your forehead and cheekbones.","Steam lifts faintly from the path — earth breathing out.","You step onto stepping-stones set in moss.","Each stone is cool and sure underfoot.","Bamboo creaks and whispers in a light breeze.","The sound is green. The sound is calm.","Smell wet leaves, stone, and a faint sweetness of tea plants nearby.","Pause beside a small pond.","Koi move like slow thoughts beneath the surface.","Sun flecks warm your wrists as you rest them on the rail.","A breeze cools the dampness at your temples.","Freshness in. Softness out.","Follow a covered walkway of worn wood.","The boards are cool in shade, warmer where light falls.","You sit on a bench facing raked gravel and one perfect stone.","Nothing needs rearranging.","Feel the quiet geometry settle your mind.","Warmth returns as cloud thins — a kind hand on your shoulders.","Then shade again, cool and restful.","Sip imaginary tea. Taste warmth. Feel the cup’s heat in your palms.","Outside the garden, life continues. Inside, time loosens.","Walk once more beneath bamboo.","Let the tall stalks sway your breath into the same easy rhythm.","Cool drip from a leaf finds your wrist — a tiny fresh surprise.","Then sun again, warm on the same spot until it dries.","You belong to this peace for as long as you stay.","And a thread of it will come with you when you leave.","Sit once more. Hands open on your knees.","Warmth wherever light touches. Coolness in the shade of bamboo.","Inhale the after-rain freshness.","Exhale into the raked quiet of stone and gravel.","Nothing sharp remains. Only soft edges and enough air.","Return to the pond for a final pause.","Ripples from a fallen drop widen and vanish.","Sun flecks dance, then still.","Warmth on the cheekbone. Cool mist-memory in the nose.","Bow slightly to the garden — a small inward nod.","Walk the stepping-stones once more, slower than before.","Cool moss between stones. Warm wood of the bridge rail.","Bamboo speaks in leaf-language overhead.","You understand enough of it: stay, soften, continue.","At the threshold, feel both worlds — garden peace and ordinary day.","You may braid them.","Inhale freshness for the braid.","Exhale warmth into the hands, ready to meet what comes.","The garden remains, whether you are looking or not.","Now let the story rest, and stay with sensation.","Inhale the freshness of this place.","Exhale into its warmth and quiet.","Inhale.","Exhale.","Again. Soft inhale.","Longer exhale.","Feel the body held by the ground of this imagined world.","Inhale.","Exhale.","If thoughts wander, return to warmth on the skin.","Or to cool air at the nose.","Inhale.","Exhale.","Inhale.","Exhale.","Stay. Soften. Continue.","Inhale.","Exhale.","One more easy cycle.","Inhale.","Exhale.","Linger in this feeling for a few more breaths.","Warmth. Softness. Enoughness.","You can return to this place whenever you need it.","It lives in your attention, not only in imagination.","Begin to deepen the breath.","Feel the room around you again.","Wiggle the fingers. Soften the toes.","When you are ready, open your eyes.","Take one more easy breath.","Carry this calm into whatever comes next."]}}`),i={"soft-drone":{name:`Soft Drone`},"warm-pad":{name:`Warm Pad`},"ocean-hum":{name:`Ocean Hum`},"mixkit-109-deep-meditation":{name:`Deep Meditation`},"mixkit-324-smooth-meditation":{name:`Smooth Meditation`},"mixkit-365-relaxation-meditation":{name:`Relaxation Meditation`},"mixkit-18-singing-bowl-meditation":{name:`Singing Bowl Meditation`},"mixkit-21-indian-meditations":{name:`Indian Meditations`},"mixkit-345-nature-meditation":{name:`Nature Meditation`},"mixkit-442-nature-yoga":{name:`Nature Yoga`},"mixkit-139-spirit-in-the-woods":{name:`Spirit in the Woods`},"mixkit-148-forest-mist-whispers":{name:`Forest Mist Whispers`},"mixkit-138-forest-treasure":{name:`Forest Treasure`},"mixkit-127-valley-sunset":{name:`Valley Sunset`},"mixkit-444-yoga-song":{name:`Yoga Song`},"mixkit-325-yoga-tune":{name:`Yoga Tune`},"mixkit-27-serene-moments":{name:`Serene Moments`},"mixkit-669-harp-relax":{name:`Harp Relax`},"mixkit-168-staring-at-the-night-sky":{name:`Staring at the Night Sky`},"mixkit-419-pilates-and-yoga":{name:`Pilates and Yoga`}},a={"foundations-to-peak":{name:`Foundations → Peak Warrior`,description:`Build capacity over four weeks: gentle floor, Sun A heat, standing flow, then a longer warrior peak. Tap each week’s “use” when you are ready to advance.`,weeks:[{label:`Week 1 · Arrive`},{label:`Week 2 · Heat`},{label:`Week 3 · Stand`},{label:`Week 4 · Peak`}]},"calm-month":{name:`Calm Month`,description:`A quieter month for the nervous system: morning mobility, yin for hips and spine, then a restorative evening. Use one week at a time; stay longer on a week if you need it.`,weeks:[{label:`Week 1 · Mobility`},{label:`Week 2 · Yin hips`},{label:`Week 3 · Yin spine`},{label:`Week 4 · Restore`}]}},o={poses:e,routines:t,learn:n,meditations:r,music:i,progressions:a};export{o as default,n as learn,r as meditations,i as music,e as poses,a as progressions,t as routines};